    /// Whether peer-sync palette entries are registered.
    pub fn peer_sync_enabled(&self) -> bool {
        self.peer_sync_enabled
    }

    /// Session-local presence controls as shown in trusted chrome. Used by
    /// semantic inspection so an agent can verify what it is publishing and
    /// whether this view is attached to somebody else.
    pub(crate) fn presence_snapshot(&self) -> (ui::StatusSharing, Option<String>, Option<String>) {
        (
            self.status_sharing,
            self.local_status.clone(),
            self.followed_peer.clone(),
        )
    }

    /// Install the closure that carries out [`PeerSyncRequest`]s. Without
    /// one, requests fail visibly as unavailable when the frame pump drains
    /// them.
    #[must_use]
    pub fn with_peer_sync_bridge(mut self, bridge: PeerSyncBridge) -> Self {
        self.set_peer_sync_bridge(bridge);
        self
    }

    /// [`Self::with_peer_sync_bridge`] for a host that is already
    /// built — the native compositor constructs its host inside a
    /// `FrameBuilder` before it has a network handle to bridge to.
    pub fn set_peer_sync_bridge(&mut self, bridge: PeerSyncBridge) {
        self.peer_sync.set_bridge(bridge);
    }

    /// Carry peer-sync requests out on `worker`, off the frame loop: the
    /// session network's, whose requests wait on relays and the disk. The
    /// frame pump applies each outcome once it is back.
    pub fn set_peer_sync_worker(&mut self, worker: PeerSyncWorker) {
        self.peer_sync.set_worker(worker);
    }

    /// Attach the compositor-owned clipboard history to trusted shell chrome.
    pub fn set_clipboard_manager_bridge(&mut self, bridge: ClipboardManagerBridge) {
        self.clipboard_manager_bridge = Some(bridge);
    }

    /// Attach the authenticated personal-device and local-output control
    /// surface. An absent bridge renders an honest unprovisioned state.
    pub fn set_device_fabric_bridge(&mut self, bridge: DeviceFabricBridge) {
        self.device_fabric_bridge = Some(std::rc::Rc::clone(&bridge));
        self.search_registry.register_or_replace(std::rc::Rc::new(
            crate::shell::search::providers::DeviceContinuityActionsProvider::new(
                std::rc::Rc::clone(&bridge),
            ),
        ));
        if let Some(realtime) = self.realtime_continuity_bridge.as_ref() {
            self.search_registry.register_or_replace(std::rc::Rc::new(
                crate::shell::search::providers::CallContinuityActionsProvider::new(
                    std::rc::Rc::clone(realtime),
                    bridge,
                ),
            ));
        }
        self.last_search_query = "\0continuity-provider-rebound\0".into();
        self.last_search_revision.clear();
    }

    /// Attach trusted shell-only call handoff controls. The app sees semantic
    /// lifecycle edges, never the certified-device picker or raw source IDs.
    pub fn set_realtime_continuity_bridge(&mut self, bridge: RealtimeContinuityBridge) {
        self.realtime_continuity_bridge = Some(std::rc::Rc::clone(&bridge));
        if let Some(devices) = self.device_fabric_bridge.as_ref() {
            self.search_registry.register_or_replace(std::rc::Rc::new(
                crate::shell::search::providers::CallContinuityActionsProvider::new(
                    bridge,
                    std::rc::Rc::clone(devices),
                ),
            ));
        }
        self.last_search_query = "\0call-continuity-provider-rebound\0".into();
        self.last_search_revision.clear();
    }

    fn realtime_continuity_call(
        &self,
        action: RealtimeContinuityUiAction,
    ) -> Result<crate::shell::collab_broker_capnp::RealtimeContinuityUiView, String> {
        self.realtime_continuity_bridge.as_ref().map_or_else(
            || Ok(crate::shell::collab_broker_capnp::RealtimeContinuityUiView::default()),
            |bridge| bridge(action),
        )
    }

    fn device_fabric_call(&self, action: DeviceFabricUiAction) -> Result<DeviceFabricView, String> {
        self.device_fabric_bridge.as_ref().map_or_else(
            || Err("Personal device fabric is not available in this session".into()),
            |bridge| bridge(action),
        )
    }

    /// Attach the encrypted same-person credential store. Sessions without a
    /// provisioned identity simply keep the existing password prompt.
    pub fn set_wifi_secret_bridge(&mut self, bridge: WifiSecretBridge) {
        self.wifi_secret_bridge = Some(bridge);
    }

    fn clipboard_manager_call(
        &self,
        action: ClipboardManagerAction,
    ) -> Vec<crate::compositor::selection::ClipboardHistorySnapshot> {
        self.clipboard_manager_bridge
            .as_ref()
            .map_or_else(Vec::new, |bridge| bridge(action))
    }

    fn filtered_clipboard_history(
        &self,
    ) -> Vec<crate::compositor::selection::ClipboardHistorySnapshot> {
        let mut history = self.clipboard_manager_call(ClipboardManagerAction::Snapshot);
        if self.qs_clipboard_query.trim().is_empty() {
            return history;
        }
        let fabric = self.device_fabric_call(DeviceFabricUiAction::Snapshot).ok();
        history.retain(|item| {
            clipboard_history_matches_query(item, &self.qs_clipboard_query, fabric.as_ref())
        });
        history
    }

    /// Supply identities the host has already verified (for example, through
    /// Contacts or a previous in-person verification). The invite sheet may
    /// reuse only these exact keys for its “someone I know” choices.
    pub fn set_remembered_invitees(&mut self, invitees: Vec<RememberedInvitee>) {
        self.peer_sync_overlay.set_remembered_invitees(invitees);
    }

    /// Install the session-local bridge that binds application viewports to
    /// the participant selected in the People popover.
    pub fn set_follow_bridge(&mut self, bridge: FollowBridge) {
        self.follow_bridge = Some(bridge);
    }

    /// Install the peer-presence publisher for the visual Follow cue. The
    /// compositor provides this only with an authenticated peer network.
    pub fn set_follow_presence_bridge(&mut self, bridge: FollowPresenceBridge) {
        self.follow_presence_bridge = Some(bridge);
    }

    pub fn set_status_presence_bridge(&mut self, bridge: StatusPresenceBridge) {
        self.status_presence_bridge = Some(bridge);
        if self.status_sharing != ui::StatusSharing::Off && self.local_status.is_some() {
            self.publish_local_status(self.local_status.clone());
        }
    }

    pub fn set_active_tab_presence_bridge(&mut self, bridge: ActiveTabPresenceBridge) {
        self.active_tab_presence_bridge = Some(bridge);
        self.published_active_tab = None;
    }

    fn refresh_active_tab_presence(&mut self) {
        let current = self.chrome.as_ref().and_then(|chrome| {
            let state = chrome.borrow();
            let room = state
                .tree()
                .desktop
                .active_workspace()
                .map(|workspace| workspace.room)?;
            Some((room, state.active_tab_id()?))
        });
        if current == self.published_active_tab {
            return;
        }
        let Some(bridge) = self.active_tab_presence_bridge.as_ref() else {
            self.published_active_tab = current;
            return;
        };
        if let Some((room, tab)) = self.published_active_tab {
            bridge(room, tab, false);
        }
        if let Some((room, tab)) = current {
            bridge(room, tab, true);
        }
        self.published_active_tab = current;
    }

    /// Carry `job` out, applying its outcome now when it is known now and
    /// from [`Self::pump_peer_sync`] once the worker has it.
    fn dispatch_peer_sync(
        &mut self,
        job: peer_sync_dispatch::Job,
        follow: peer_sync_dispatch::FollowUp,
    ) {
        if let Some((follow, outcome)) = self.peer_sync.submit(job, follow) {
            self.apply_peer_sync(follow, outcome);
        }
    }

    /// Apply one request's outcome: to the card, or as the answer of the
    /// action that asked.
    fn apply_peer_sync(
        &mut self,
        follow: peer_sync_dispatch::FollowUp,
        outcome: Result<PeerSyncResponse, String>,
    ) {
        use peer_sync_dispatch::FollowUp;
        match follow {
            FollowUp::Card {
                request,
                copy_result,
            } => {
                self.peer_sync_overlay
                    .finish_typed_request(&request, outcome, copy_result);
                if matches!(
                    request,
                    PeerSyncRequest::IssueInviteFor { .. } | PeerSyncRequest::CancelInvitation(_)
                ) {
                    self.refresh_pending_invitations();
                }
            }
            FollowUp::Action {
                request,
                request_id,
            } => {
                if matches!(
                    request,
                    PeerSyncRequest::IssueInvitation(_) | PeerSyncRequest::CancelInvitation(_)
                ) {
                    self.refresh_pending_invitations();
                }
                let output = outcome.and_then(|response| {
                    crate::shell::peer_sync_overlay::network_action_output(&request, response)
                });
                self.complete_peer_sync_action(request_id, output);
            }
            FollowUp::Pairing { request } => self.apply_pairing(&request, outcome),
            FollowUp::Directory { request } => self.apply_directory(&request, outcome),
            FollowUp::Ignore => {}
        }
    }

    /// Bring the person into each site workspace whose join installed: its
    /// site's app opens there (off the loop), and the arrival line names it
    /// and who is here. While the directory sheet is up, its rows follow
    /// the joins. Answers whether anything changed.
    fn pump_arrivals(&mut self) -> bool {
        let now = Instant::now();
        self.arrival_line.expire(now);
        if self.directory_sheet.visible() {
            self.directory_sheet.set_joins(self.peer_sync.site_joins());
        }
        let arrivals = self.peer_sync.arrive();
        let Some(arrival) = arrivals.last() else {
            return false;
        };
        let Some(chrome) = self.chrome.as_ref() else {
            return true;
        };
        let shown = {
            let state = chrome.borrow();
            state
                .tree()
                .desktop
                .workspaces
                .iter()
                .find(|workspace| workspace.room == arrival.room)
                .map(|workspace| {
                    let people = workspace
                        .collaborators
                        .iter()
                        .map(|person| crate::shell::arrival_line::Present {
                            name: person.name.clone(),
                            id: person.id.clone(),
                        })
                        .collect::<Vec<_>>();
                    (workspace.name.clone(), people)
                })
        };
        if let Some((name, people)) = shown {
            self.arrival_line.show(&name, people, now);
            self.introduce_joined(arrival.room);
        }
        true
    }

    /// Open "Join a workspace…" and ask the directories for what they list.
    pub(super) fn open_directory(&mut self) {
        let request = self.directory_sheet.open();
        self.run_directory_request(request);
    }

    /// Carry out what the directory sheet asked: reading directories and
    /// joining off the frame loop, switching and the join field here.
    fn run_directory_request(&mut self, request: crate::shell::directory_sheet::DirectoryRequest) {
        use crate::shell::directory_sheet::DirectoryRequest;
        let network = match request {
            DirectoryRequest::Fetch { site } => PeerSyncRequest::Directory { site },
            DirectoryRequest::Join(listing) => PeerSyncRequest::JoinListed(listing),
            DirectoryRequest::Open(listing) => {
                self.directory_sheet.close();
                if let Some(room) = listing.room {
                    self.switch_to_room(room, None);
                }
                return;
            }
            DirectoryRequest::LinkOrCode(text) => {
                self.directory_sheet.close();
                self.peer_sync_overlay.prompt_connect_with(&text);
                // A link or a code the person typed joins at once; the field
                // shows it joining, or why not.
                let text: String = text.split_whitespace().collect();
                if !text.is_empty() {
                    self.run_peer_sync_request(&PeerSyncRequest::AcceptInvite(text), false);
                }
                return;
            }
        };
        self.dispatch_directory(network);
    }

    /// Run one of the directory's network requests on the worker.
    fn dispatch_directory(&mut self, request: PeerSyncRequest) {
        self.dispatch_peer_sync(
            peer_sync_dispatch::Job {
                request: request.clone(),
                require_pending: false,
                workspace: self.active_workspace_id(),
            },
            peer_sync_dispatch::FollowUp::Directory { request },
        );
    }

    /// Show the workspace a join or Open leads to: `workspace` when a slot
    /// was made for it, else the one showing `room`. The workspace motion
    /// is the one every switch takes.
    fn switch_to_room(
        &self,
        room: crate::shell::state::RoomId,
        workspace: Option<crate::shell::state::WorkspaceId>,
    ) {
        let Some(chrome) = self.chrome.as_ref() else {
            return;
        };
        let mut state = chrome.borrow_mut();
        let target = workspace.or_else(|| {
            state
                .tree()
                .desktop
                .workspaces
                .iter()
                .find(|candidate| candidate.room == room)
                .map(|candidate| candidate.id)
        });
        if let Some(target) = target {
            state.overlays.overview = false;
            state.switch_to_workspace(target);
        }
    }

    /// Show what a directory request answered: the listings on the sheet,
    /// the workspace a join made, or why not; a workspace's publication in
    /// its settings; a report's acknowledgement.
    fn apply_directory(
        &mut self,
        request: &PeerSyncRequest,
        outcome: Result<PeerSyncResponse, String>,
    ) {
        match (request, outcome) {
            (PeerSyncRequest::Directory { .. }, Ok(PeerSyncResponse::Directory(listings))) => {
                self.directory_sheet.show(listings);
            }
            (
                PeerSyncRequest::JoinListed(_),
                Ok(PeerSyncResponse::JoinedWorkspace { room, workspace }),
            ) => {
                self.directory_sheet.joined();
                self.switch_to_room(room, workspace);
            }
            (PeerSyncRequest::Directory { .. } | PeerSyncRequest::JoinListed(_), Err(error)) => {
                self.directory_sheet.failed(&error);
            }
            (
                PeerSyncRequest::Publication(room) | PeerSyncRequest::Publish { room, .. },
                outcome,
            ) => {
                if let Some(chrome) = self.chrome.as_ref() {
                    let mut state = chrome.borrow_mut();
                    match outcome {
                        Ok(PeerSyncResponse::Publication(publication)) => {
                            if publication.moved {
                                // Making it public moved it to the person's
                                // host: say so once, in a sentence.
                                let name = state
                                    .tree()
                                    .desktop
                                    .workspaces
                                    .iter()
                                    .find(|workspace| workspace.room == publication.room)
                                    .map(|workspace| workspace.name.clone())
                                    .unwrap_or_default();
                                state.push_notification(
                                    t_args("directory-moved", &[("name", name.into())]),
                                    String::new(),
                                );
                            }
                            if publication.room != *room {
                                state.set_publication(
                                    *room,
                                    Ok(crate::shell::network::Publication::private(*room)),
                                );
                            }
                            state.set_publication(publication.room, Ok(publication));
                        }
                        Ok(_) => {
                            state.set_publication(*room, Err(t("peer-sync-unexpected-response")))
                        }
                        Err(error) => state.set_publication(*room, Err(error)),
                    }
                    state.bump();
                }
            }
            // The room's governance answers with the bot list itself, as
            // its change reaches this device; only a refusal is said here.
            (PeerSyncRequest::AskForBot { ask, .. }, Err(error)) => {
                if let Some(chrome) = self.chrome.as_ref() {
                    let title = match ask {
                        crate::shell::network::BotAsk::Add { .. } => t("bots-add-failed"),
                        crate::shell::network::BotAsk::Remove { .. } => t("bots-remove-failed"),
                    };
                    chrome.borrow_mut().push_warning_notification(title, &error);
                }
            }
            (PeerSyncRequest::AskForBot { .. }, Ok(_)) => {}
            (PeerSyncRequest::ReportWorkspace { .. }, outcome) => {
                if let Some(chrome) = self.chrome.as_ref() {
                    let mut state = chrome.borrow_mut();
                    match outcome {
                        Ok(_) => {
                            state.push_notification(
                                t("directory-reported"),
                                t("directory-reported-body"),
                            );
                        }
                        Err(error) => {
                            state.push_warning_notification(t("directory-report-failed"), &error);
                        }
                    }
                }
            }
            (_, Ok(_)) => {
                self.directory_sheet
                    .failed(&t("peer-sync-unexpected-response"));
            }
            (_, Err(error)) => {
                tracing::debug!(%error, "a directory request failed");
            }
        }
    }

    /// Route one event to the directory sheet while it is open; whether it
    /// took it. Every key belongs to it, as to the join field.
    fn handle_directory_event(
        &mut self,
        event: &WindowEvent,
        modifiers: winit::event::Modifiers,
    ) -> bool {
        let outcome = self
            .directory_sheet
            .handle_event(event, modifiers, self.last_cursor);
        if let Some(request) = outcome.request {
            self.run_directory_request(request);
        }
        outcome.consumed
    }

    fn draw_directory_sheet(
        &mut self,
        scene: &mut Scene,
        transform: Affine,
        text_renderer: &mut TextRenderer,
        theme: &Theme,
    ) {
        self.directory_sheet
            .draw(self.rect, scene, transform, text_renderer, theme);
    }

    /// Carry out one pairing request on the worker.
    /// Open "Pair a new device" and ask the network for its link.
    pub(super) fn open_pairing(&mut self) {
        self.peer_sync_overlay.prompt_pair();
        self.dispatch_pairing(PeerSyncRequest::InviteDevice);
    }

    fn dispatch_pairing(&mut self, request: PeerSyncRequest) {
        self.dispatch_peer_sync(
            peer_sync_dispatch::Job {
                request: request.clone(),
                require_pending: false,
                workspace: self.active_workspace_id(),
            },
            peer_sync_dispatch::FollowUp::Pairing { request },
        );
    }

    /// Show what a pairing request answered: the link on the sheet, a
    /// notification for each device newly asking, the answer's outcome.
    fn apply_pairing(
        &mut self,
        request: &PeerSyncRequest,
        outcome: Result<PeerSyncResponse, String>,
    ) {
        match (request, outcome) {
            (
                PeerSyncRequest::InviteDevice,
                Ok(PeerSyncResponse::PairingInvite {
                    link,
                    expires_at_ms,
                }),
            ) => {
                self.peer_sync_overlay.show_pairing(link);
                self.pairing_until_ms = expires_at_ms;
            }
            (PeerSyncRequest::InviteDevice, Err(error)) => {
                self.peer_sync_overlay.pairing_failed(&error);
            }
            (PeerSyncRequest::DevicesAsking, Ok(PeerSyncResponse::DevicesAsking(asking))) => {
                if let Some(chrome) = self.chrome.as_ref() {
                    let mut state = chrome.borrow_mut();
                    for device in &asking {
                        self.device_labels
                            .insert(device.digest, device.label.clone());
                        state.push_device_asking(device);
                    }
                }
            }
            (PeerSyncRequest::AnswerDevice { digest, approve }, Ok(_)) => {
                let label = self.device_labels.remove(digest).unwrap_or_default();
                if *approve {
                    self.peer_sync_overlay.pairing_done(&label);
                    if let Some(chrome) = self.chrome.as_ref() {
                        chrome.borrow_mut().push_notification(
                            t_args("pairing-done", &[("device", label.into())]),
                            String::new(),
                        );
                    }
                }
                self.pairing_until_ms = 0;
            }
            (PeerSyncRequest::AnswerDevice { .. }, Err(error)) => {
                if let Some(chrome) = self.chrome.as_ref() {
                    chrome.borrow_mut().push_warning_notification(
                        t_args("pairing-answer-failed", &[("error", error.into())]),
                        String::new(),
                    );
                }
            }
            (PeerSyncRequest::DevicesAsking, Err(error)) => {
                tracing::debug!(%error, "the devices asking could not be read");
            }
            _ => {}
        }
    }

    /// While a pairing link of this computer's admits a device, ask its host
    /// for the devices asking under it now and then; and send the person's
    /// answers to them.
    fn pump_pairing(&mut self) {
        let answers = self
            .chrome
            .as_ref()
            .map_or_else(Vec::new, |chrome| chrome.borrow_mut().take_device_answers());
        for (digest, approve) in answers {
            self.dispatch_pairing(PeerSyncRequest::AnswerDevice { digest, approve });
        }
        if self.pairing_until_ms <= tilo_clock::unix_now_ms()
            || self.peer_sync.in_flight(&PeerSyncRequest::DevicesAsking)
            || self
                .pairing_polled_at
                .is_some_and(|at| at.elapsed() < PAIRING_POLL_INTERVAL)
        {
            return;
        }
        self.pairing_polled_at = Some(std::time::Instant::now());
        self.dispatch_pairing(PeerSyncRequest::DevicesAsking);
    }

    /// The workspace a peer-sync request made now is for.
    fn active_workspace_id(&self) -> Option<crate::shell::state::WorkspaceId> {
        self.chrome
            .as_ref()
            .map(|chrome| chrome.borrow().tree().desktop.active)
    }

    fn complete_peer_sync_action(
        &self,
        request_id: Option<u64>,
        result: Result<serde_json::Value, String>,
    ) {
        if let (Some(request_id), Some(chrome)) = (request_id, self.chrome.as_ref()) {
            chrome
                .borrow_mut()
                .complete_peer_sync_request(request_id, result);
        }
    }

    /// Drain the palette's peer-sync intents and act on them, once per
    /// frame from [`Widget::update`]. `/invite` mints a token; `/connect`
    /// opens the token prompt. Both write their outcome into chrome; a
    /// network request's outcome lands here once the worker has it.
    /// Answers whether anything changed.
    fn pump_peer_sync(&mut self) -> bool {
        let answered = self.peer_sync.answered();
        let mut changed = !answered.is_empty();
        for (follow, outcome) in answered {
            self.apply_peer_sync(follow, outcome);
        }
        changed |= self.pump_arrivals();
        // One enrollment poll at a time: a poll that installs the room
        // publishes the state file on the worker.
        let polling = self
            .peer_sync
            .in_flight(&PeerSyncRequest::PollEnrollment(0))
            || self
                .peer_sync
                .in_flight(&PeerSyncRequest::CancelEnrollment(0));
        if !polling && let Some(request) = self.peer_sync_overlay.pending_enrollment_request() {
            self.run_peer_sync_request(&request, false);
        }
        self.pump_pairing();
        let actions = self.chrome.as_ref().map_or_else(Vec::new, |chrome| {
            chrome.borrow_mut().take_peer_sync_requests()
        });
        changed |= !actions.is_empty();
        for action in actions {
            let (request_id, action) = match action {
                PeerSyncAction::Tracked { request_id, action } => (Some(request_id), *action),
                action => (None, action),
            };
            match action {
                PeerSyncAction::IssueInviteFor { name, copy } => {
                    let _ = copy;
                    self.open_invite_manager();
                    self.peer_sync_overlay.prompt_invite_for(name);
                    self.complete_peer_sync_action(request_id, Ok(serde_json::Value::Null));
                }
                PeerSyncAction::PromptInvite => {
                    self.open_invite_manager();
                    self.complete_peer_sync_action(request_id, Ok(serde_json::Value::Null));
                }
                PeerSyncAction::PromptConnect => {
                    self.peer_sync_overlay.prompt_connect();
                    self.complete_peer_sync_action(request_id, Ok(serde_json::Value::Null));
                }
                PeerSyncAction::BrowseDirectory => {
                    self.open_directory();
                    self.complete_peer_sync_action(request_id, Ok(serde_json::Value::Null));
                }
                PeerSyncAction::ReportWorkspace { room, reason } => {
                    self.dispatch_directory(PeerSyncRequest::ReportWorkspace { room, reason });
                    self.complete_peer_sync_action(request_id, Ok(serde_json::Value::Null));
                }
                PeerSyncAction::Publish { room, listing } => {
                    self.dispatch_directory(PeerSyncRequest::Publish { room, listing });
                    self.complete_peer_sync_action(request_id, Ok(serde_json::Value::Null));
                }
                PeerSyncAction::AskForBot { room, ask } => {
                    self.dispatch_directory(PeerSyncRequest::AskForBot { room, ask });
                    self.complete_peer_sync_action(request_id, Ok(serde_json::Value::Null));
                }
                PeerSyncAction::ReadPublication { room } => {
                    if !self
                        .peer_sync
                        .in_flight(&PeerSyncRequest::Publication(room))
                    {
                        self.dispatch_directory(PeerSyncRequest::Publication(room));
                    }
                    self.complete_peer_sync_action(request_id, Ok(serde_json::Value::Null));
                }
                PeerSyncAction::PairDevice => {
                    self.open_pairing();
                    self.complete_peer_sync_action(request_id, Ok(serde_json::Value::Null));
                }
                PeerSyncAction::LeaveSite { room } => {
                    self.dispatch_peer_sync(
                        peer_sync_dispatch::Job {
                            request: PeerSyncRequest::LeaveSite(room),
                            require_pending: false,
                            workspace: self.active_workspace_id(),
                        },
                        peer_sync_dispatch::FollowUp::Ignore,
                    );
                    self.complete_peer_sync_action(request_id, Ok(serde_json::Value::Null));
                }
                PeerSyncAction::Network { workspace, request } => {
                    self.run_network_action(workspace, request, request_id);
                }
                #[expect(
                    clippy::unreachable,
                    reason = "the palette queues a tracked request around one plain action, never another tracked one"
                )]
                PeerSyncAction::Tracked { .. } => unreachable!("tracked requests are unwrapped"),
            }
        }
        changed
    }

    /// Carry out one invitation action's network request against the
    /// workspace it was authorized in; its JSON output answers the action
    /// `request_id` once the request is back. Resend and cancel are scoped
    /// to that workspace's pending invitations, so an id from another
    /// workspace is not pending here.
    fn run_network_action(
        &mut self,
        workspace: crate::shell::state::WorkspaceId,
        request: PeerSyncRequest,
        request_id: Option<u64>,
    ) {
        let active = self.chrome.as_ref().and_then(|chrome| {
            chrome
                .borrow()
                .tree()
                .desktop
                .active_workspace()
                .map(|active| active.id)
        });
        if active != Some(workspace) {
            self.complete_peer_sync_action(
                request_id,
                Err("the active workspace changed before the invitation request ran".into()),
            );
            return;
        }
        let require_pending = matches!(
            request,
            PeerSyncRequest::ResendInvitation(_) | PeerSyncRequest::CancelInvitation(_)
        );
        self.dispatch_peer_sync(
            peer_sync_dispatch::Job {
                request: request.clone(),
                require_pending,
                workspace: Some(workspace),
            },
            peer_sync_dispatch::FollowUp::Action {
                request,
                request_id,
            },
        );
    }

    fn run_peer_sync_request(&mut self, request: &PeerSyncRequest, copy_result: bool) {
        // The card's request is still being carried out: a second press
        // would mint or redeem twice.
        if self.peer_sync.in_flight(request) {
            return;
        }
        self.peer_sync_overlay.begin_request(request);
        self.dispatch_peer_sync(
            peer_sync_dispatch::Job {
                request: request.clone(),
                require_pending: false,
                workspace: self.active_workspace_id(),
            },
            peer_sync_dispatch::FollowUp::Card {
                request: request.clone(),
                copy_result,
            },
        );
    }

    fn open_invite_manager(&mut self) {
        if !self.may_invite_here() {
            if let Some(chrome) = self.chrome.as_ref() {
                chrome.borrow_mut().push_notification(
                    t("host-invite-unavailable-title"),
                    t("host-invite-unavailable-body"),
                );
            }
            return;
        }
        let (context, room_invitees) = self.chrome.as_ref().map_or_else(
            || (InviteContext::default(), Vec::new()),
            |chrome| {
                let state = chrome.borrow();
                let local_user = state.local_user_id.clone();
                let tree = state.tree();
                let workspace_name = tree.desktop.active_workspace().map_or_else(
                    || t("host-this-workspace"),
                    |workspace| workspace.name.clone(),
                );
                let room_invitees = tree
                    .desktop
                    .active_workspace()
                    .map(|workspace| tree.trusted_identity_projection(workspace.room))
                    .map(|projection| {
                        projection
                            .humans
                            .into_iter()
                            .filter(|human| {
                                let root = hex::encode(human.root_public_key);
                                local_user != root && local_user != format!("ed25519:{root}")
                            })
                            .map(|human| RememberedInvitee {
                                name: human.display_name,
                                user_public_key: human.root_public_key,
                                verification: crate::shell::i18n::t(
                                    "invite-workspace-verified-identity",
                                ),
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                let snapshot = (
                    InviteContext {
                        workspace_name,
                        inviter_name: local_user,
                    },
                    room_invitees,
                );
                drop(tree);
                drop(state);
                snapshot
            },
        );
        // Best-effort: without a running network there is nothing to start.
        self.dispatch_peer_sync(
            peer_sync_dispatch::Job {
                request: PeerSyncRequest::PrepareInvitation,
                require_pending: false,
                workspace: self.active_workspace_id(),
            },
            peer_sync_dispatch::FollowUp::Ignore,
        );
        self.peer_sync_overlay.set_invite_context(context);
        self.peer_sync_overlay
            .merge_remembered_invitees(room_invitees);
        self.peer_sync_overlay.prompt_invite();
        self.refresh_pending_invitations();
    }

    fn refresh_pending_invitations(&mut self) {
        let request = PeerSyncRequest::ListPendingInvitations;
        self.dispatch_peer_sync(
            peer_sync_dispatch::Job {
                request: request.clone(),
                require_pending: false,
                workspace: self.active_workspace_id(),
            },
            peer_sync_dispatch::FollowUp::Card {
                request,
                copy_result: false,
            },
        );
    }

    /// Route one event to the peer-sync card, returning whether it was
    /// consumed. While a prompt is open every key belongs to it — a
    /// base64 token shares characters with shell chords, so anything
    /// that leaked past would both corrupt the token and fire an action.
    fn handle_peer_sync_event(
        &mut self,
        event: &WindowEvent,
        modifiers: winit::event::Modifiers,
    ) -> bool {
        let PeerSyncEventOutcome {
            consumed,
            request,
            copy_result,
        } = self
            .peer_sync_overlay
            .handle_event(event, modifiers, self.last_cursor);
        if let Some(request) = request {
            self.run_peer_sync_request(&request, copy_result);
        }
        consumed
    }

    /// Override where the band under the top bar begins
    /// ([`CHROME_TOP_OFFSET_PX`] by default).
    #[must_use]
    pub fn with_chrome_top(mut self, y: f32) -> Self {
        self.chrome_top_y = y;
        self
    }

    /// Tell the host which displays it is painting across, so
    /// [`GroupRow`]s can size against per-display strip widths.
    pub fn set_output_geometry(&mut self, outputs: &[OutputGeometry]) {
        if self.outputs != outputs {
            self.outputs = outputs.to_vec();
            self.reconcile_display_partition();
        }
    }

    /// The displays the host was last told about.
    pub fn output_geometry(&self) -> &[OutputGeometry] {
        &self.outputs
    }

    /// Start painting each display's number and name when Settings has
    /// asked to identify displays since the last check. The compositor
    /// calls this at its settings reload point.
    pub fn poll_display_identify(&mut self) -> bool {
        let outputs = if self.outputs.is_empty() {
            vec![OutputGeometry::unscaled(
                0.0,
                0.0,
                self.rect.width(),
                self.rect.height(),
            )]
        } else {
            self.outputs.clone()
        };
        let started = self.display_identify.poll(&outputs, Instant::now());
        if started && let Some(chrome) = self.chrome.as_ref() {
            chrome.borrow_mut().bump();
        }
        started
    }

    /// Keep OS identification labels in the current shared display order.
    pub(crate) fn number_identified_displays(
        &mut self,
        layout: &settings_store::person_displays::Layout,
    ) {
        self.display_identify
            .number_by_shared_order(&self.outputs, layout);
    }

    /// Ask the person to keep or revert display transaction `transaction`,
    /// which a layout tool applied. Settings and the Super+P sheet ask in
    /// their own UI; this is for changes from anywhere else.
    pub fn show_display_confirmation(
        &mut self,
        transaction: u64,
        tool: Option<settings_store::display_tools::DisplayTool>,
    ) {
        self.layers
            .display_confirm
            .show(transaction, tool, Instant::now());
        self.bump_chrome();
    }

    /// Tell the person `tool` applied a display layout again right after
    /// they reverted it, and was refused instead of asking them again.
    pub fn report_refused_display_reapply(
        &mut self,
        tool: Option<&settings_store::display_tools::DisplayTool>,
    ) {
        let title = tool.map_or_else(
            || t("display-tool-reapply-refused-unknown"),
            |tool| {
                t_args(
                    "display-tool-reapply-refused",
                    &[("tool", ui::i18n::ArgValue::from(tool.name().to_owned()))],
                )
            },
        );
        if let Some(chrome) = self.chrome.as_ref() {
            chrome.borrow_mut().push_notification(title, String::new());
        }
    }

    /// Whether the keep-or-revert prompt for a tool's display change is up.
    /// It owns the keyboard and pointer while it is.
    pub fn display_confirmation_visible(&self) -> bool {
        self.layers.display_confirm.visible()
    }

    /// Re-read the transaction the prompt asks about now: close it if it
    /// was answered elsewhere, revert it if its time ran out. Returns
    /// whether the prompt closed.
    pub fn poll_display_confirmation(&mut self) -> bool {
        let closed = self.layers.display_confirm.poll(Instant::now(), true);
        if closed && let Some(chrome) = self.chrome.as_ref() {
            chrome.borrow_mut().bump();
        }
        closed
    }

    /// Where the prompt's card sits on each display.
    pub fn display_confirmation_cards(&self) -> Vec<crate::shell::display_confirm::ConfirmCard> {
        self.layers.display_confirm.cards(&self.layer_outputs())
    }

    /// Every display's rect; the host's bounds alone before it knows of any.
    pub(super) fn layer_outputs(&self) -> Vec<Rect> {
        if self.outputs.is_empty() {
            vec![self.rect]
        } else {
            self.outputs.iter().map(OutputGeometry::rect).collect()
        }
    }

    /// Where stacked layers may place themselves, over `outputs` from
    /// [`Self::layer_outputs`].
    pub(super) fn layer_geometry<'a>(&self, outputs: &'a [Rect]) -> LayerGeometry<'a> {
        LayerGeometry {
            viewport: self.rect,
            outputs,
            focused_output: self.focused_output().map(|output| output.rect()),
        }
    }

    /// The identify cards on screen right now, one per display.
    pub fn display_identify_labels(&self) -> Vec<crate::shell::display_identify::IdentifyLabel> {
        self.display_identify.labels(Instant::now()).to_vec()
    }

    /// Per-display strip widths: full extent plus width actually
    /// available to window groups, less the strip's edge gutters. Falls back to the host's own
    /// rect when the compositor hasn't pushed geometry yet (`--mode
    /// hosted`).
    fn strip_output_spans(&self) -> Vec<OutputSpan> {
        let outputs: Vec<OutputGeometry> = if self.outputs.is_empty() {
            // `self.rect` is zero on a first frame (only set in
            // apply_layout, this runs during build_layout); no spans
            // lets `GroupRow::basis_for` fall back to its own chain.
            if self.rect.width() <= 1.0 {
                return Vec::new();
            }
            vec![OutputGeometry::unscaled(
                0.0,
                0.0,
                self.rect.width(),
                self.rect.height(),
            )]
        } else {
            self.outputs.clone()
        };
        let strip_left = 0.0_f64;
        outputs
            .iter()
            .filter(|o| o.width > 0.0)
            .map(|o| {
                let leads = strip_left >= o.x && strip_left < o.x + o.width;
                let leading = if leads { STRIP_EDGE_GUTTER_PX } else { 0.0 };
                OutputSpan {
                    x: o.x,
                    width: o.width,
                    usable: (o.width - leading - STRIP_TRAILING_GUTTER_PX).max(1.0),
                }
            })
            .collect()
    }

    /// Register the per-strip [`GroupRow`] raw pointers harvested at
    /// build time, used each frame to feed the reconciler without
    /// re-walking the widget tree.
    ///
    /// SAFETY: every pointer in `ptrs` must address a `GroupRow` owned by
    /// the content subtree this host wraps. The caller (currently
    /// [`build_tilo_overlay_host_with_chrome`](crate::shell::build_tilo_overlay_host_with_chrome)) is responsible for
    /// upholding that invariant by capturing the pointer immediately after
    /// `Box::new(strip_row)` and passing the same `Box` into the content
    /// tree — the `Box<T>` -> `Box<dyn Widget>` unsizing coercion keeps
    /// the heap address stable.
    #[must_use]
    pub fn with_group_row_ptrs(mut self, ptrs: HashMap<StripId, *mut GroupRow>) -> Self {
        self.group_row_ptrs = ptrs;
        self
    }

    /// Record which workspace the injected content was built for, so
    /// `Self::resync_workspace_content` can detect the first switch away.
    #[must_use]
    pub fn with_content_workspace(mut self, ws_raw: u64) -> Self {
        self.content_built_for_ws = Some(ws_raw);
        self.content_built_empty = self.chrome.as_ref().and_then(|chrome| {
            let state = chrome.borrow();
            let tree = state.tree();
            tree.desktop
                .active_workspace()
                .map(|workspace| !workspace.has_windows())
        });
        self
    }

    /// Swaps the workspace-scoped content when the active workspace changes
    /// or grows a strip with no row. Content root and pointer map rebuild
    /// TOGETHER via [`crate::shell::build_workspace_root`], so no
    /// reconciler ever observes a pointer into a freed row. A new strip has
    /// no incremental path — [`Self::resync_strips_from_tree`] splices by
    /// strip id and skips strips it has no row for — so a rebuild (costing
    /// scroll offsets, not focus, which lives in the tree) is the only
    /// option, and it's rare. Returns `true` on a swap. Runs at the top of
    /// both [`Widget::update`] and [`Widget::take_structure_dirty`] — the
    /// shots driver's relayout-only path skips `update`.
    fn resync_workspace_content(&mut self) -> bool {
        let Some(chrome) = self.chrome.clone() else {
            return false;
        };
        {
            let st = chrome.borrow();
            let tree = st.tree();
            if let Some(surface) = self.desktop_surface_mut() {
                surface.retire_departed_requested_groups(&tree.desktop);
            }
        }
        let closing_visual = self
            .desktop_surface_mut()
            .is_some_and(|surface| surface.close_animation_in_flight());
        let (rebuild, stale) = {
            let st = chrome.borrow();
            let tree = st.tree();
            let active_raw = tree.desktop.active.raw();
            let active_empty = tree
                .desktop
                .active_workspace()
                .is_some_and(|workspace| !workspace.has_windows());
            // A kept workspace that was removed (or became another room)
            // lets go of its apps now, not at the next switch; so does one a
            // tab moved out of, before the reconcile that follows mounts the
            // tab where it went. Tabs move only with the chrome's revision.
            let moved_tabs = st.revision != self.last_chrome_revision;
            let stale = self.parked_workspaces.stale(&tree.desktop, moved_tabs);
            let rebuild = match self.content_built_for_ws {
                // Hand-made test content: latch, never rebuild over it.
                None => {
                    self.content_built_for_ws = Some(active_raw);
                    None
                }
                Some(cur)
                    if cur == active_raw
                        && (self.content_built_empty == Some(active_empty) || closing_visual)
                        && self.rows_cover_active_strips(&tree) =>
                {
                    None
                }
                Some(_) => Some((tree.desktop.clone(), st.record_creation_errors(&tree))),
            };
            (rebuild, stale)
        };
        if !stale.is_empty() {
            self.desktop_close_reports
                .extend(parked_workspaces::close(stale));
        }
        let Some((desktop, failures)) = rebuild else {
            return false;
        };
        let swapped = self.rebuild_workspace_content(&chrome, &desktop, &failures);
        if swapped {
            // A chord already started this switch's frames, before demand
            // was sampled; keep its source rather than lengthening them.
            let source = if self.workspace_switch_holding() {
                self.workspace_switch_source
            } else {
                ui::tokens::MotionSource::Pointer
            };
            self.start_workspace_switch_frames(source);
        }
        swapped
    }

    /// Rebuilds the desktop surface for `desktop` and replaces the row
    /// pointer map with it. Tabs whose tile is unchanged in the same room
    /// keep their live hosts, so a strip added or removed beside them costs
    /// no app state. A different workspace puts back the content kept for it
    /// ([`parked_workspaces`]) or gets fresh content, and the content it
    /// replaces is kept. Takes the desktop alone, with `failures` read
    /// beside it under the same tree lock, so a workspace switch never
    /// copies the replication documents.
    fn rebuild_workspace_content(
        &mut self,
        chrome: &Chrome,
        desktop: &crate::shell::state::DesktopTree,
        failures: &std::collections::BTreeMap<u64, String>,
    ) -> bool {
        let records = chrome.borrow().records().clone();
        let switching = self
            .content_built_for_ws
            .is_some_and(|shown| shown != desktop.active.raw());
        if switching && self.desktop_surface_mut().is_some() {
            self.switch_workspace_content(chrome, desktop, failures, &records);
        }
        if let Some(surface) = self.desktop_surface_mut() {
            if !switching {
                let surface_chrome = crate::shell::workspace_surface_chrome(desktop, chrome);
                let state = chrome.borrow();
                surface.rebuild_retaining(
                    desktop,
                    &records,
                    &mut crate::shell::NativeTileResolver {
                        inputs: &state.hosted_inputs,
                        failures,
                    },
                    surface_chrome,
                );
            }
            for id in surface.strip_ids() {
                if let Some(row) = surface.row_mut(id) {
                    for group in &mut row.groups {
                        crate::shell::tab_documents::apply_creation_failures(group, failures);
                    }
                }
            }
            // The rebuild replaced every row; the old addresses are gone.
            self.group_row_ptrs = crate::shell::surface_row_ptrs(surface);
        } else {
            let (root, ptrs) =
                crate::shell::build_desktop_root(desktop, &records, chrome, failures);
            // Settle outgoing components while the old root still owns them,
            // so their recovery reports survive the swap.
            self.desktop_close_reports
                .extend(ui::component_lifecycle::close_components(
                    self.content.as_mut(),
                ));
            self.desktop_close_reports.extend(
                ui::component_lifecycle::take_component_close_reports(self.content.as_mut()),
            );
            // Replace content and pointer map in one step: dropping the old
            // root frees every old GroupRow, and the map must never outlive
            // the rows it points into.
            self.content = root;
            self.group_row_ptrs = ptrs;
        }
        self.content_built_for_ws = Some(desktop.active.raw());
        self.content_built_empty = desktop
            .active_workspace()
            .map(|workspace| !workspace.has_windows());
        self.workspace_content_layout_dirty = true;
        true
    }

    /// Show `desktop`'s active workspace in place of the one shown until
    /// now, which is kept: its content as it was left when it was kept, with
    /// what changed in the tree since reconciled, or else built fresh. The
    /// caller re-reads the row pointers.
    fn switch_workspace_content(
        &mut self,
        chrome: &Chrome,
        desktop: &crate::shell::state::DesktopTree,
        failures: &std::collections::BTreeMap<u64, String>,
        records: &ui::record::RecordStore,
    ) {
        use tilo_desktop::composition::{DesktopSurface, ReconcileOutcome};
        // Before the target is mounted: a tab that moved here from a kept
        // workspace is mounted by this one alone.
        let moved_on = self.parked_workspaces.stale(desktop, true);
        self.desktop_close_reports
            .extend(parked_workspaces::close(moved_on));
        let kept = self.parked_workspaces.take(desktop.active.raw());
        let resumed = kept.is_some();
        let incoming = kept.unwrap_or_else(|| {
            crate::shell::build_desktop_root(desktop, records, chrome, failures).0
        });
        let mut outgoing = std::mem::replace(&mut self.content, incoming);
        if let Some(shown) = outgoing
            .as_any_mut()
            .and_then(|content| content.downcast_mut::<DesktopSurface>())
            && let Some(next) = self.desktop_surface_mut()
        {
            next.take_pointer_from(shown);
        }
        // The outgoing rows stay alive, kept; the map moves to the new ones
        // before anything walks it.
        self.group_row_ptrs.clear();
        let dropped = match self.content_built_for_ws {
            Some(shown) => self.parked_workspaces.park(shown, outgoing),
            None => vec![outgoing],
        };
        self.desktop_close_reports
            .extend(parked_workspaces::close(dropped));
        if !resumed {
            return;
        }
        let outcome = {
            let state = chrome.borrow();
            self.desktop_surface_mut().map(|surface| {
                surface.reconcile(
                    desktop,
                    records,
                    &mut crate::shell::NativeTileResolver {
                        inputs: &state.hosted_inputs,
                        failures,
                    },
                )
            })
        };
        if outcome == Some(ReconcileOutcome::RebuildRequired) {
            // Its strips changed while it was away: new chrome around the
            // same mounted apps (the surface is this workspace's room).
            let surface_chrome = crate::shell::workspace_surface_chrome(desktop, chrome);
            let state = chrome.borrow();
            if let Some(surface) = self.desktop_surface_mut() {
                surface.rebuild_retaining(
                    desktop,
                    records,
                    &mut crate::shell::NativeTileResolver {
                        inputs: &state.hosted_inputs,
                        failures,
                    },
                    surface_chrome,
                );
            }
        }
    }

    /// The workspaces whose content is kept while another one is shown,
    /// least recently shown first.
    #[cfg(test)]
    pub(crate) fn kept_workspaces_for_tests(&self) -> Vec<u64> {
        self.parked_workspaces.workspaces()
    }

    /// The shared desktop surface, when the content is one. Hand-built test
    /// content is not.
    /// A frame was presented. The compositor never marks its content drawn,
    /// so the window groups' once-per-drawn-frame motion is told here.
    pub(crate) fn frame_presented(&mut self) {
        if let Some(surface) = self.desktop_surface_mut() {
            surface.frame_presented();
        }
    }

    fn desktop_surface_mut(&mut self) -> Option<&mut tilo_desktop::composition::DesktopSurface> {
        self.content.as_any_mut()?.downcast_mut()
    }

    /// Does the content tree have a row for every strip of the active
    /// workspace? A strip with no row can't be drawn (the incremental
    /// resync looks it up by id); extra rows point at strips that went away.
    fn rows_cover_active_strips(&self, tree: &crate::shell::state::WorkspaceTree) -> bool {
        let Some(ws) = tree.desktop.active_workspace() else {
            return true;
        };
        ws.strips.len() == self.group_row_ptrs.len()
            && ws
                .strips
                .iter()
                .all(|s| self.group_row_ptrs.contains_key(&s.id))
    }

    /// Test hook for the workspace-content reconcile — mirrors the
    /// per-frame call the update/layout paths make.
    pub fn tick_workspace_content_for_tests(&mut self) -> bool {
        self.resync_workspace_content()
    }

    /// Shell chrome on screen that holds a secret: the administrator
    /// authentication and network-secrets sheets, a shortcut step that asks
    /// for a secret answer, the quick-settings pane
    /// while it asks for a Wi-Fi passphrase, the display sheet while it asks
    /// for an `AirPlay` PIN or password, a Bluetooth pairing dialog, and the
    /// setup steps that restore or back up the identity (passphrases and a
    /// nearby device's pairing code). A capture always draws these as the placeholder — see
    /// [`crate::shell::capture_protection`].
    pub fn secret_prompt_rects(&self) -> Vec<Rect> {
        let mut rects = Vec::new();
        let now = Instant::now();
        if let Some(rect) = self
            .onboarding
            .as_ref()
            .and_then(crate::onboarding_view::OnboardingView::secret_rect)
        {
            rects.push(rect);
        }
        if self.portal_dialogs.holds_secret()
            && let Some(layout) = self.portal_dialogs.layout(self.overlay_area())
        {
            rects.push(layout.sheet);
        }
        let asks_passphrase = self
            .chrome
            .as_ref()
            .is_some_and(|chrome| chrome.borrow().quick_settings.wifi_password.is_some());
        if asks_passphrase && self.qs_motion.is_visible(now) {
            // The dropdown's own paint clip: it covers the pane at every
            // point of its open/close scale.
            rects.push(self.quick_settings_rect().inflate(8.0, 16.0));
        }
        rects.extend(self.projection_overlay.secret_prompt_rect(now));
        rects.extend(self.pairing.secret_rect());
        rects
    }

    /// Draw Bluetooth pairing questions from `handle` instead of the
    /// session's. Tests use a private handle so their prompts never reach
    /// another host.
    #[doc(hidden)]
    pub fn set_pairing_prompt_handle(&mut self, handle: crate::bluetooth::PairingPromptHandle) {
        self.pairing = crate::bluetooth_prompt::PairingOverlay::new(handle);
    }

    /// The Bluetooth pairing dialog, when one is open.
    pub fn pairing_prompt(&self) -> Option<&crate::bluetooth_prompt::PairingPromptView> {
        self.pairing.view()
    }

    /// Serve administrator-authentication and network-secrets sheets (and
    /// every other portal sheet) from `queue` instead of the session's.
    /// Tests use a private queue so their sheets never reach another host.
    #[doc(hidden)]
    pub fn set_portal_dialog_queue(
        &mut self,
        queue: crate::shell::portal_dialog::PortalDialogQueue,
    ) {
        self.portal_dialogs = PortalDialogController::new(queue);
        self.register_authentication_actions();
    }

    /// On-screen rect of the tile hosting foreign wayland surface
    /// `surface_id`, or `None` when no *visible* tile hosts it. Walks the
    /// live widget tree, not persisted state, so the answer is what's
    /// actually painted — what the compositor needs to size the client at.
    pub fn foreign_surface_rect(&mut self, surface_id: u64) -> Option<Rect> {
        let wanted = format!("foreign-surface-{surface_id}");
        for &row_ptr in self.group_row_ptrs.values() {
            // SAFETY: same contract as every other `group_row_ptrs`
            // accessor — the pointer comes from a `Box<GroupRow>` owned by
            // the content tree, the host outlives the content, and
            // `&mut self` gives us unaliased access for this call.
            let row: &mut GroupRow = unsafe { &mut *row_ptr };
            for group in &mut row.groups {
                let Some(host) = group.active_host_mut() else {
                    continue;
                };
                let ui::widget::TileContent::App(app) = host.content() else {
                    continue;
                };
                if app.test_id() == Some(wanted.as_str()) {
                    let rect = app.get_rect();
                    if rect.width() > 0.0 && rect.height() > 0.0 {
                        return Some(rect);
                    }
                }
            }
        }
        None
    }

    /// Replace one matching peer-window card with a live, session-local
    /// decoder. Returns false when the remote app has no corresponding tab;
    /// the caller may retry when the replicated window description arrives.
    pub fn mount_peer_stream(&mut self, stream: &crate::shell::peer_view::PeerStreamStart) -> bool {
        let crate::shell::peer_view::PeerStreamStart {
            source_peer,
            surface: surface_id,
            local_peer,
            ref app_id,
            ref codec,
            display_size,
            hdr_static_metadata,
            ref input_sink,
            ref keyframe_sink,
            tab,
        } = *stream;
        let key = (source_peer, surface_id);
        if let Some(tab_id) = self.peer_stream_tabs.get(&key).copied() {
            for &row_ptr in self.group_row_ptrs.values() {
                // SAFETY: rows are boxed by this host and `&mut self` makes
                // the traversal exclusive, as in `foreign_surface_rect`.
                let row: &mut GroupRow = unsafe { &mut *row_ptr };
                for group in &mut row.groups {
                    let Some(host) = group.host_for_tab_mut(tab_id) else {
                        continue;
                    };
                    let ui::widget::TileContent::App(app) = host.content_mut() else {
                        continue;
                    };
                    // A repeated stream start for a mounted share: the sender
                    // may have switched codec, so the view follows it.
                    if let Some(view) = app
                        .as_any_mut()
                        .and_then(|any| any.downcast_mut::<crate::shell::peer_view::PeerView>())
                    {
                        view.restart_stream(codec, display_size);
                        return true;
                    }
                }
            }
            // A workspace/root rebuild invalidated the runtime widget while
            // leaving the session alive. Forget only the runtime binding;
            // the caller's retained start descriptor remounts it below.
            self.peer_stream_tabs.remove(&key);
        }
        let Some(chrome) = self.chrome.clone() else {
            return false;
        };
        let tab_id = self.stream_tab(&chrome, app_id, tab);
        let Some(tab_id) = tab_id else {
            return false;
        };
        let mut peer_view = crate::shell::peer_view::PeerView::new_for_stream(
            surface_id,
            local_peer,
            codec,
            crate::diagnostics::PeerSurfaceMetrics::default(),
            &crate::shell::hdr_display::DisplayCapabilities::sdr_default(),
            hdr_static_metadata,
        );
        peer_view.restart_stream(codec, display_size);
        peer_view.set_input_sink(std::sync::Arc::clone(input_sink));
        peer_view.set_keyframe_sink(std::sync::Arc::clone(keyframe_sink));
        peer_view.set_picture_wake(self.peer_picture_wake.clone());
        for &row_ptr in self.group_row_ptrs.values() {
            // SAFETY: identical to `foreign_surface_rect`: rows are boxed by
            // this host and `&mut self` makes this traversal exclusive.
            let row: &mut GroupRow = unsafe { &mut *row_ptr };
            for group in &mut row.groups {
                if let Some(host) = group.host_for_tab_mut(tab_id) {
                    host.replace_content(ui::widget::TileContent::App(Box::new(peer_view)));
                    self.peer_stream_tabs.insert(key, tab_id);
                    return true;
                }
            }
        }
        false
    }

    /// The tab a stream starting now mounts into: exactly the one it names,
    /// wherever it is, or for a stream naming none the first free tab of its
    /// app in the active workspace.
    fn stream_tab(&self, chrome: &Chrome, app_id: &str, tab: u64) -> Option<u64> {
        let state = chrome.borrow();
        let tree = state.tree();
        let unclaimed = |id: u64| !self.peer_stream_tabs.values().any(|claimed| *claimed == id);
        if tab != 0 {
            tree.desktop
                .workspaces
                .iter()
                .flat_map(|workspace| &workspace.strips)
                .flat_map(|strip| &strip.window_groups)
                .flat_map(|group| &group.tabs)
                .find(|candidate| {
                    candidate.id == tab
                        && matches!(
                            candidate.tile,
                            crate::shell::state::TileContent::HostedWindow { .. }
                                | crate::shell::state::TileContent::PeerWindow { .. }
                        )
                })
                .map(|candidate| candidate.id)
                .filter(|id| unclaimed(*id))
        } else {
            tree.desktop.active_workspace().and_then(|workspace| {
                workspace.strips.iter().find_map(|strip| {
                    strip.window_groups.iter().find_map(|group| {
                        group.tabs.iter().find_map(|tab| match &tab.tile {
                            crate::shell::state::TileContent::PeerWindow {
                                app_id: candidate,
                                ..
                            }
                            | crate::shell::state::TileContent::HostedWindow {
                                app_id: candidate,
                                ..
                            } if candidate == app_id && unclaimed(tab.id) => Some(tab.id),
                            _ => None,
                        })
                    })
                })
            })
        }
    }

    /// Decode the next encoded unit (sequence number `seq`) into the mounted
    /// peer view. Returns whether the decoder took it.
    pub fn push_peer_stream_frame(
        &mut self,
        source_peer: u64,
        surface_id: u64,
        seq: u64,
        encoded: &[u8],
        latency_ns: Option<u64>,
    ) -> bool {
        self.peer_stream_view_mut(source_peer, surface_id)
            .is_some_and(|view| {
                matches!(
                    view.push_encoded_with_latency(seq, encoded, latency_ns),
                    crate::shell::peer_view::PushOutcome::Decoded
                        | crate::shell::peer_view::PushOutcome::DroppedOldest
                        | crate::shell::peer_view::PushOutcome::Pending
                )
            })
    }

    /// How the loop learns that a peer-stream picture finished decoding:
    /// peer views never wait for their pictures, so `wake` (run on a media
    /// thread) brings the loop back to [`Self::collect_late_peer_pictures`].
    /// Views mounted from now on use it.
    pub fn set_peer_picture_wake(&mut self, wake: media::realtime::PictureWake) {
        self.peer_picture_wake = Some(wake);
    }

    /// Show every peer-stream picture that finished decoding after its frame
    /// was pushed. A window that stops changing sends no further frame to
    /// carry its last picture out of the decoder, so the loop collects it.
    /// Returns whether any view took a new picture.
    pub fn collect_late_peer_pictures(&mut self) -> bool {
        if self.peer_stream_tabs.is_empty() {
            return false;
        }
        let streams: Vec<(u64, u64)> = self.peer_stream_tabs.keys().copied().collect();
        let mut collected = false;
        for (source_peer, surface_id) in streams {
            if let Some(view) = self.peer_stream_view_mut(source_peer, surface_id)
                && view.picture_pending()
            {
                collected |= view.collect_late_picture().is_some();
            }
        }
        collected
    }

    /// The view showing the stream of `surface_id` from `source_peer`.
    pub fn peer_stream_view_mut(
        &mut self,
        source_peer: u64,
        surface_id: u64,
    ) -> Option<&mut crate::shell::peer_view::PeerView> {
        let tab_id = self
            .peer_stream_tabs
            .get(&(source_peer, surface_id))
            .copied()?;
        for &row_ptr in self.group_row_ptrs.values() {
            // SAFETY: same row ownership invariant as `mount_peer_stream`.
            let row: &mut GroupRow = unsafe { &mut *row_ptr };
            for group in &mut row.groups {
                let Some(host) = group.host_for_tab_mut(tab_id) else {
                    continue;
                };
                let ui::widget::TileContent::App(app) = host.content_mut() else {
                    return None;
                };
                return app
                    .as_any_mut()
                    .and_then(|any| any.downcast_mut::<crate::shell::peer_view::PeerView>());
            }
        }
        None
    }

    /// Whether a view shows the stream of `surface_id` from `source_peer`.
    pub fn has_peer_stream(&self, source_peer: u64, surface_id: u64) -> bool {
        self.peer_stream_tabs
            .contains_key(&(source_peer, surface_id))
    }

    /// Drop a session-local peer decoder and restore the persisted
    /// peer-window card underneath it.
    pub fn unmount_peer_stream(&mut self, source_peer: u64, surface_id: u64) -> bool {
        let Some(tab_id) = self.peer_stream_tabs.remove(&(source_peer, surface_id)) else {
            return false;
        };
        let tile = self.chrome.as_ref().and_then(|chrome| {
            let state = chrome.borrow();
            let tree = state.tree();
            tree.desktop.active_workspace().and_then(|workspace| {
                workspace.strips.iter().find_map(|strip| {
                    strip.window_groups.iter().find_map(|group| {
                        group
                            .tabs
                            .iter()
                            .find(|tab| tab.id == tab_id)
                            .map(|tab| tab.tile.clone())
                    })
                })
            })
        });
        let Some(tile) = tile else {
            return false;
        };
        for &row_ptr in self.group_row_ptrs.values() {
            // SAFETY: same row ownership invariant as `mount_peer_stream`.
            let row: &mut GroupRow = unsafe { &mut *row_ptr };
            for group in &mut row.groups {
                if let Some(host) = group.host_for_tab_mut(tab_id) {
                    host.replace_content(crate::shell::to_ui_tile(&tile));
                    return true;
                }
            }
        }
        false
    }

    /// Whether any tab on screen is still holding a place for an app that
    /// hasn't drawn yet (see [`ui::widget::WindowGroup::any_tile_opening`]).
    /// A group in this state requests animation frames for as long as it
    /// waits — deliberately indistinguishable from a wedged animation from
    /// the outside; this method is how a caller waiting for the tree to go
    /// quiet tells them apart.
    pub fn any_tile_opening(&mut self) -> bool {
        let mut any_opening = false;
        for &row_ptr in self.group_row_ptrs.values() {
            // SAFETY: same contract as every other `group_row_ptrs`
            // accessor — the pointer comes from a `Box<GroupRow>` owned by
            // the content tree, the host outlives the content, and
            // `&mut self` gives us unaliased access for this call.
            let row: &mut GroupRow = unsafe { &mut *row_ptr };
            // Do not short-circuit: asking every group is what latches a
            // newly published client frame as presented. Returning at the
            // first opening group would leave later foreign tabs opening
            // forever even though their buffers are already available.
            any_opening = row
                .groups
                .iter()
                .map(ui::widget::WindowGroup::any_tile_opening)
                .fold(any_opening, |seen, opening| opening || seen);
        }
        any_opening
    }

    /// Drain app-owned requests for shell chrome after the app's event path
    /// has run. The request carries stable resource identity, so opening
    /// Activity does not depend on a file's current path or display label.
    pub fn connect_native_terminal(
        &mut self,
        connection: u64,
        writer: std::sync::mpsc::Sender<Vec<u8>>,
    ) {
        if self.terminal_device_shell.is_none() {
            let provider = crate::shell::search::providers::terminal_device_shell::TerminalDeviceShellProvider::default();
            self.search_registry
                .register(std::rc::Rc::new(provider.clone()));
            self.terminal_device_shell = Some(provider);
        }
        if let Some(provider) = &self.terminal_device_shell {
            provider.connect(connection, writer);
        }
    }

    pub fn complete_native_terminal(
        &mut self,
        connection: u64,
        request: u64,
        result: Result<serde_json::Value, String>,
    ) {
        if let Some(provider) = &self.terminal_device_shell {
            provider.complete(connection, request, result);
        }
    }

    pub fn disconnect_native_terminal(&mut self, connection: u64) {
        if let Some(provider) = &self.terminal_device_shell {
            provider.disconnect(connection);
        }
    }

    pub fn request_native_host_shell_allow(&mut self, writer: std::sync::mpsc::Sender<Vec<u8>>) {
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        let (prompt, pending) = crate::shell::host_shell_allow::native_prompt(writer);
        let mut chrome = chrome.borrow_mut();
        chrome.pending_grants.push_back(prompt);
        chrome.bump();
        self.host_shell_allows.push(pending);
    }

    /// Settings may request topology through the same admitted app-host channel.
    /// Same identity and topology observations never mint an input lease.
    /// # Errors
    /// Rejects non-Settings callers, locked or non-owner sessions, and unavailable peers.
    pub fn request_device_display_move(
        &self,
        app_id: &str,
        request: settings_store::device_displays::DeviceDisplayMove,
    ) -> Result<(), String> {
        let admitted = app_id == "so.tilo.settings"
            && self.chrome.as_ref().is_some_and(|chrome| {
                let state = chrome.borrow();
                !state.session_locked() && is_active_workspace_owner(&state)
            });
        if !admitted {
            return Err(t("device-fabric-error-layout-changed"));
        }
        let bridge = self
            .device_fabric_bridge
            .as_ref()
            .ok_or_else(|| t("device-fabric-error-no-identity"))?;
        bridge(DeviceFabricUiAction::MoveDisplay(request)).map(|_| ())
    }

    fn active_tab_app_id(
        chrome: &crate::shell::chrome_state::Chrome,
        source_tab: crate::shell::state::TabId,
    ) -> Option<String> {
        let state = chrome.borrow();
        state
            .tree()
            .desktop
            .active_workspace()
            .and_then(|workspace| {
                workspace.strips.iter().find_map(|strip| {
                    strip.window_groups.iter().find_map(|group| {
                        group
                            .tabs
                            .iter()
                            .any(|tab| tab.id == source_tab)
                            .then(|| state.tab_app_id(strip.id, group.id, source_tab))
                            .flatten()
                    })
                })
            })
    }

    fn drain_app_host_intents(&mut self) {
        self.host_shell_allows.retain_mut(|pending| !pending.poll());
        let mut intents = Vec::new();
        for &row_ptr in self.group_row_ptrs.values() {
            // SAFETY: `group_row_ptrs` points into `self.content`; `&mut self`
            // makes this walk exclusive, matching the other row accessors.
            let row: &mut GroupRow = unsafe { &mut *row_ptr };
            for group in &mut row.groups {
                let source_tab = group.active_tab_id();
                let Some(host) = group.active_host_mut() else {
                    continue;
                };
                // Not `content_mut`: that ends the tile's document lifetime,
                // and this runs on every frame.
                if let Some(intent) = host.take_host_intent() {
                    intents.push((source_tab, intent));
                }
            }
        }
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        for (source_tab, intent) in intents {
            match intent {
                ui::widget::AppHostIntent::MoveDeviceDisplay { request, reply } => {
                    let Some(reply) = reply.upgrade() else {
                        continue;
                    };
                    let app_id = Self::active_tab_app_id(&chrome, source_tab);
                    reply.borrow_mut().result = Some(self.request_device_display_move(
                        app_id.as_deref().unwrap_or_default(),
                        request,
                    ));
                }
                ui::widget::AppHostIntent::ShowWorkspaceActivity {
                    resource_id,
                    version_id,
                    entry,
                } => {
                    let entry_id = entry.as_ref().map(|entry| *entry.id.as_bytes());
                    if let Some(entry) = entry {
                        self.room_activity.open_external_entry(entry);
                    }
                    chrome.borrow_mut().open_room_activity(Some(
                        crate::shell::chrome_state::ActivityFocus {
                            resource_id: Some(resource_id),
                            resource_version: version_id,
                            entry_id,
                            ..crate::shell::chrome_state::ActivityFocus::default()
                        },
                    ));
                }
                ui::widget::AppHostIntent::OpenSearch(request) => {
                    self.open_app_search(source_tab, &request);
                }
                ui::widget::AppHostIntent::AllowHostShell { reply } => {
                    let (prompt, pending) = crate::shell::host_shell_allow::prompt(reply);
                    let mut st = chrome.borrow_mut();
                    st.pending_grants.push_back(prompt);
                    st.bump();
                    self.host_shell_allows.push(pending);
                }
                ui::widget::AppHostIntent::OpenDocument {
                    path,
                    capability,
                    token,
                    reply,
                } => {
                    let Some(reply) = reply.upgrade() else {
                        continue;
                    };
                    let Ok(mut reply) = reply.try_borrow_mut() else {
                        continue;
                    };
                    if !reply.is_pending(token) {
                        continue;
                    }
                    Self::complete_document_open_request(
                        &chrome,
                        source_tab,
                        &path,
                        &capability,
                        token,
                        &mut reply,
                    );
                }
            }
        }
    }

    /// Resolve the one capability-bound Files request that drain admitted.
    /// Keeping the authorization immediately beside the actual opener avoids
    /// any generic app intent becoming a filesystem-read capability.
    fn complete_document_open_request(
        chrome: &crate::shell::chrome_state::Chrome,
        source_tab: crate::shell::state::TabId,
        path: &std::path::Path,
        capability: &ui::widget::DocumentOpenCapability,
        token: u64,
        reply: &mut ui::widget::DocumentOpenReply,
    ) {
        let authorized_source = {
            let state = chrome.borrow();
            let files_app_id = crate::shell::state::AppKind::FileExplorer.app_id();
            state.active_tab_id() == Some(source_tab)
                && state.active_app_id().as_deref() == Some(files_app_id.as_str())
                && state
                    .hosted_inputs
                    .accepts_document_open_capability(capability)
        };
        if !authorized_source {
            reply.cancel(token);
            return;
        }
        reply.complete(token, crate::shell::open_document_from_files(chrome, path));
    }

    /// Reconciles the shared desktop surface with the live tree. Groups and
    /// tabs are spliced in place, so untouched rows keep their host state
    /// (scroll, tab selection); a changed strip set rebuilds the surface.
    /// Cheap on the no-op path — one u64 compare against
    /// `last_chrome_revision`.
    fn resync_strips_from_tree(&mut self) -> bool {
        let Some(chrome) = self.chrome.clone() else {
            return false;
        };
        chrome.borrow_mut().retry_new_tab_records();
        self.place_new_groups();
        let current_rev = chrome.borrow().revision;
        let closing_visuals = self
            .desktop_surface_mut()
            .is_some_and(|surface| surface.has_closing_visuals());
        if current_rev == self.last_chrome_revision && !closing_visuals {
            return false;
        }
        self.last_chrome_revision = current_rev;
        let outcome = {
            let st = chrome.borrow();
            let records = st.records().clone();
            let tree = st.tree();
            let failures = st.record_creation_errors(&tree);
            let Some(surface) = self.desktop_surface_mut() else {
                return false;
            };
            surface.reconcile(
                &tree.desktop,
                &records,
                &mut crate::shell::NativeTileResolver {
                    inputs: &st.hosted_inputs,
                    failures: &failures,
                },
            )
        };
        match outcome {
            tilo_desktop::composition::ReconcileOutcome::Unchanged => false,
            tilo_desktop::composition::ReconcileOutcome::Updated => true,
            tilo_desktop::composition::ReconcileOutcome::RebuildRequired => {
                let (desktop, failures) = {
                    let st = chrome.borrow();
                    let tree = st.tree();
                    (tree.desktop.clone(), st.record_creation_errors(&tree))
                };
                self.rebuild_workspace_content(&chrome, &desktop, &failures)
            }
        }
    }

    /// Pushes the compositor's transient fullscreen state onto every
    /// strip's [`GroupRow`] so the owning strip promotes while others
    /// collapse. Idempotent. Called from [`Widget::update`],
    /// [`Widget::build_layout`], and `FrameBuilder::relayout` *before* the
    /// structure-dirty check, so a promotion/restore triggers the rebuild.
    pub fn sync_fullscreen_from_chrome(&mut self) {
        if self.group_row_ptrs.is_empty() {
            return;
        }
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        // Client `xdg_toplevel.set_fullscreen` wins over a user-expanded
        // group if both are set.
        let (fs_group, single, client_fullscreen) = {
            let st = chrome.borrow();
            let client = st.fullscreen_group();
            let single = st.single_strip().then(|| st.active_strip_id()).flatten();
            (
                client.or_else(|| st.maximized_group()),
                single,
                client.is_some(),
            )
        };
        // The live client tree and this rendered tree aren't yet unified,
        // so a fullscreen id we don't host must count as "no fullscreen"
        // — otherwise every strip hides around a group that isn't here.
        let owned = fs_group.is_some_and(|gid| {
            self.group_row_ptrs
                .values()
                // SAFETY: see the per-row note below — same `group_row_ptrs`
                // contract; here we only read `group_ids()`.
                .any(|&p| unsafe { (*p).group_ids().contains(&gid) })
        });
        // Publish the presentation edge before `take_structure_dirty` can
        // rebuild the top bar. Restore is especially sensitive: rebuilding
        // while this still says `true` leaves the chrome hidden, with no
        // later structural edge to rebuild it again.
        chrome.borrow_mut().set_fullscreen_presentation(owned);
        // On a desktop spread across displays a fullscreen covers its own
        // display only: the rows of other strips step aside there and stay
        // on every other display, beside that display's own chrome.
        let covered = if owned && client_fullscreen {
            fs_group.and_then(|group| self.fullscreen_display_of(group))
        } else {
            None
        };
        chrome.borrow_mut().set_fullscreen_display(covered);
        for (&strip, &row_ptr) in &self.group_row_ptrs {
            // SAFETY: same contract as every other `group_row_ptrs` accessor —
            // the pointer comes from a `Box<GroupRow>` owned by the content
            // tree, the host outlives the content, and `&mut self` gives us
            // unaliased access for the duration of this call.
            let row: &mut GroupRow = unsafe { &mut *row_ptr };
            // Neither keeps a gutter: an expanded window fills the display.
            row.set_promotion_keeps_gutter(false);
            row.set_promotion_keeps_controls(!client_fullscreen);
            match fs_group {
                Some(gid) if owned && row.group_ids().contains(&gid) => {
                    row.set_fullscreen(Some(gid), false);
                    row.set_covered_output(None);
                }
                Some(_) if owned => {
                    row.set_fullscreen(None, covered.is_none());
                    row.set_covered_output(covered.map(|display| display.output));
                }
                _ => {
                    row.set_fullscreen(None, single.is_some_and(|single| single != strip));
                    row.set_covered_output(None);
                }
            }
        }
    }

    /// The display the fullscreen `group` covers, while the desktop is
    /// spread across displays: the one the partition places it on.
    fn fullscreen_display_of(
        &self,
        group: GroupId,
    ) -> Option<crate::shell::chrome_state::FullscreenDisplay> {
        if !self.is_partitioned() {
            return None;
        }
        let output = self
            .chrome
            .as_ref()?
            .borrow()
            .tree()
            .desktop
            .outputs
            .display_of(group)?;
        let primary = self
            .primary_output()
            .is_some_and(|primary| primary.id == output);
        Some(crate::shell::chrome_state::FullscreenDisplay { output, primary })
    }

    /// A full-display surface — Capture Studio, the screenshot markup
    /// editor — covers the focused display: its bars sit along that
    /// display's top and bottom edges and "Screen" is that display.
    /// Across the whole desktop of a docked laptop the bars were centred on
    /// the combined width and hung from its tallest edge, which put them on
    /// the other display, partly below the panel's bottom, while the panel
    /// only greyed: Print looked broken until Escape.
    fn place_on_focused_display(&self, taffy: &mut TaffyTree<()>, node: NodeId) {
        let Some(display) = self.focused_output() else {
            return;
        };
        let area = display.rect();
        let Ok(style) = taffy.style(node) else {
            return;
        };
        let mut style = style.clone();
        style.position = Position::Absolute;
        style.inset = TaffyRect {
            left: LengthPercentageAuto::length(f32_of_f64(area.x0 - self.rect.x0)),
            right: LengthPercentageAuto::auto(),
            top: LengthPercentageAuto::length(f32_of_f64(area.y0 - self.rect.y0)),
            bottom: LengthPercentageAuto::auto(),
        };
        style.size = Size {
            width: Dimension::length(f32_of_f64(area.width())),
            height: Dimension::length(f32_of_f64(area.height())),
        };
        let _ = taffy.set_style(node, style);
    }

    /// Whether the requested fullscreen/maximized group is represented by a
    /// live retained row. Chrome stays visible until this becomes true.
    fn fullscreen_group_is_owned(&self) -> bool {
        let Some(chrome) = self.chrome.as_ref() else {
            return false;
        };
        let group = {
            let state = chrome.borrow();
            state.fullscreen_group().or_else(|| state.maximized_group())
        };
        group.is_some_and(|group| {
            self.group_row_ptrs.values().any(|&row| {
                // SAFETY: same retained-row ownership contract as
                // `sync_fullscreen_from_chrome`; this is read-only.
                unsafe { (*row).group_ids().contains(&group) }
            })
        })
    }

    fn reconcile_active_group_off_closing(&self) {
        if self.group_row_ptrs.is_empty() {
            return;
        }
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        // Take a snapshot first so the chrome borrow is dropped before the
        // mutable reconcile borrow below — avoids RefCell aliasing if any
        // reconciler step ever calls into a chrome-borrowing helper.
        let mut closing_per_strip: Vec<(StripId, Vec<GroupId>)> =
            Vec::with_capacity(self.group_row_ptrs.len());
        for (&strip_id, &ptr) in &self.group_row_ptrs {
            // SAFETY: pointer was captured from a `Box<GroupRow>` we own
            // through the content tree (see `with_group_row_ptrs`). The
            // host outlives the content, and this is a read-only deref,
            // so the pointer is valid regardless of aliasing.
            let row: &GroupRow = unsafe { &*ptr };
            let closing: Vec<GroupId> = row
                .groups
                .iter()
                .filter(|g| g.is_closing())
                .map(|g| g.id)
                .collect();
            if !closing.is_empty() {
                closing_per_strip.push((strip_id, closing));
            }
        }
        if closing_per_strip.is_empty() {
            return;
        }
        let st = chrome.borrow_mut();
        let mut changed = false;
        for (strip_id, closing) in closing_per_strip {
            let mut tree = st.tree_mut();
            let before = tree.desktop.active_group_for(strip_id);
            let after = tree
                .desktop
                .nudge_active_group_off_closing(strip_id, &closing);
            drop(tree);
            changed |= before != after;
        }
        if changed {
            // Closing the focused group's last tab changes the destination
            // for keyboard input immediately, before the fade finishes. Keep
            // that focus hand-off durable at the same boundary: a crash or
            // logout during the animation must not restart with the stale
            // closing group selected.
            st.tree().queue_save();
        }
    }

    /// Run desktop requests through the shared desktop controller with
    /// this device as the owner. Returns how many were accepted; chrome is
    /// only borrowed when there is a request.
    fn dispatch_desktop_intents(
        chrome: &Chrome,
        intents: impl IntoIterator<Item = tilo_desktop::intents::DesktopIntent>,
    ) -> usize {
        let mut intents = intents.into_iter().peekable();
        if intents.peek().is_none() {
            return 0;
        }
        let mut st = chrome.borrow_mut();
        let mut sink = crate::shell::desktop_commands::ShellCommands { chrome: &mut st };
        intents
            .filter(|intent| {
                match tilo_desktop::session_commands::dispatch(&mut sink, intent.clone()) {
                    Ok(()) => true,
                    Err(error) => {
                        tracing::warn!(?intent, %error, "desktop request refused");
                        false
                    }
                }
            })
            .count()
    }

    /// Drain every row's groups through `take`, collecting the intents it
    /// finds pending.
    fn take_group_intents(
        &self,
        mut take: impl FnMut(&mut UiWindowGroup) -> Option<tilo_desktop::intents::DesktopIntent>,
    ) -> Vec<tilo_desktop::intents::DesktopIntent> {
        let mut intents = Vec::new();
        for &ptr in self.group_row_ptrs.values() {
            // SAFETY: see field doc on `group_row_ptrs` — pointer was
            // captured from a `Box<GroupRow>` owned through the content
            // tree, the host outlives the content, and reconcile sweeps
            // run sequentially so no other path is aliasing this row.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            intents.extend(row.groups.iter_mut().filter_map(&mut take));
        }
        intents
    }

    /// Every group's pending maximize toggle, persisted through the desktop
    /// controller — without this the toggle lives only on the widget and
    /// resets on the next restart.
    fn harvest_pending_maximize_changes(&self) {
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        // The maximized chrome's `[Full screen]` chip: the same real
        // fullscreen Super+F and F11 toggle, for that group.
        let mut fullscreen = None;
        for &ptr in self.group_row_ptrs.values() {
            // SAFETY: as in `take_group_intents`.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            for group in &mut row.groups {
                if group.take_pending_fullscreen_request() {
                    fullscreen = Some(group.id);
                }
            }
        }
        if let Some(group) = fullscreen {
            chrome.borrow_mut().set_user_fullscreen_group(Some(group));
        }
        let intents = self.take_group_intents(|group| {
            tilo_desktop::intents::take_maximize(group)
                .map(tilo_desktop::intents::DesktopIntent::Local)
        });
        if intents.is_empty() {
            return;
        }
        Self::dispatch_desktop_intents(&chrome, intents);

        // The Expand interaction takes effect at this harvest boundary,
        // before the next layout. Mirror retained-row ownership into chrome
        // now so the top bar and wheel observe the same atomic transition.
        let fullscreen = self.fullscreen_group_is_owned();
        chrome.borrow_mut().set_fullscreen_presentation(fullscreen);
    }

    /// Mirrors the widget-side `TabBar::active_id` back into the persisted
    /// tree's `group.active_tab`/`active_group`/`active_strip` — without
    /// it, a tab click flips visible content but leaves search-scope
    /// helpers pointing at the group's initial tab. Runs after input
    /// (`flush_active_tab_writeback`) and before a search or palette
    /// scope is resolved, not every frame.
    fn harvest_active_tab_writeback(&self) {
        // Widgets and chrome can't be borrowed at once, so collect the
        // tuples first and apply under one chrome borrow.
        struct Writeback {
            strip: StripId,
            group: GroupId,
            tab: crate::shell::state::TabId,
        }
        if self.group_row_ptrs.is_empty() {
            return;
        }
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        let mut writes: Vec<Writeback> = Vec::new();
        for (&strip_id, &ptr) in &self.group_row_ptrs {
            // SAFETY: same contract as every other `group_row_ptrs`
            // accessor — captured from a `Box<GroupRow>` owned through
            // the content tree, host outlives the content; this is a
            // read-only deref.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            for g in &mut row.groups {
                if let Some(tab) = g.take_tab_activation() {
                    writes.push(Writeback {
                        strip: strip_id,
                        group: g.id,
                        tab,
                    });
                }
            }
        }
        if writes.is_empty() {
            return;
        }
        let st = chrome.borrow_mut();
        // Only an explicit pointer/keyboard/accessibility edge reaches this
        // list. A newly rebuilt retained row can temporarily disagree with
        // the model; treating that divergence as a click steals focus back
        // from an application which just opened. Focus is stamped only for
        // the active workspace: a newer workspace switch takes precedence
        // over a gesture made in the outgoing one.
        let mut selection_changed = false;
        let mut focus_writes: Vec<(WorkspaceId, StripId, GroupId)> = Vec::new();
        // A FileReference card is inert until the person explicitly selects
        // its tab.  Capture that activation while holding the tree, then
        // resolve/open it after releasing chrome so the normal document
        // launcher can apply its capability and hydration path.
        let mut activated_file_tabs = Vec::new();
        {
            let mut tree = st.tree_mut();
            let active_workspace = tree.desktop.active;
            for w in &writes {
                for ws in &mut tree.desktop.workspaces {
                    for strip in &mut ws.strips {
                        if strip.id != w.strip {
                            continue;
                        }
                        if let Some(group) =
                            strip.window_groups.iter_mut().find(|g| g.id == w.group)
                        {
                            // A stale `bar.active_id` (mid-detach
                            // frame) would write a phantom active-tab
                            // id and silently drop the group.
                            let tab_exists = group.tabs.iter().any(|t| t.id == w.tab);
                            if !tab_exists {
                                continue;
                            }
                            selection_changed |= group.active_tab != w.tab;
                            group.activate_tab(w.tab);
                            if ws.id == active_workspace {
                                focus_writes.push((ws.id, w.strip, w.group));
                                activated_file_tabs.push(w.tab);
                            }
                        }
                    }
                }
            }
        }
        // Activating a group's already-selected tab is still a focus edge.
        if selection_changed || !focus_writes.is_empty() {
            let mut tree = st.tree_mut();
            for (ws_id, strip_id, group_id) in focus_writes {
                selection_changed |= tree.desktop.active_strip.get(&ws_id) != Some(&strip_id)
                    || tree.desktop.active_group.get(&strip_id) != Some(&group_id);
                tree.desktop.active_strip.insert(ws_id, strip_id);
                tree.desktop.active_group.insert(strip_id, group_id);
                // Assistive activation has no pointer event to choose its display.
                if let Some(display) = tree.desktop.outputs.display_of(group_id) {
                    selection_changed |= tree.desktop.outputs.focused_display() != Some(display);
                    tree.desktop.outputs.set_focused(display);
                }
            }
            let activated_file_tabs: Vec<_> = activated_file_tabs
                .into_iter()
                .filter(|tab| tree.continuation_file_references.contains_key(tab))
                .collect();
            // Selection is session state, not merely paint state. Persist it
            // in the same input/frame boundary that accepted the click so a
            // compositor crash cannot restore the previously visible tab.
            if selection_changed {
                tree.queue_save();
            }
            drop(tree);
            drop(st);
            for tab in activated_file_tabs {
                let _ = crate::shell::doc_open::activate_continuity_file_tab(&chrome, tab);
            }
        }
    }

    /// Give every live window group the same share of its strip, and
    /// mirror it to the persisted tree the way a width drag does. Setting
    /// the tree alone wouldn't move anything — the laid-out width lives
    /// on the widget. Returns the ids touched.
    pub fn set_group_widths(&mut self, permille: u32) -> Vec<u64> {
        let mut touched: Vec<u64> = Vec::new();
        for &ptr in self.group_row_ptrs.values() {
            // SAFETY: see field doc on `group_row_ptrs`.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            for g in &mut row.groups {
                g.set_width(ui::widget::WindowWidth::Fraction(permille));
                touched.push(g.id);
            }
        }
        if touched.is_empty() {
            return touched;
        }
        if let Some(chrome) = self.chrome.clone() {
            let st = chrome.borrow_mut();
            let mut tree = st.tree_mut();
            for ws in &mut tree.desktop.workspaces {
                for strip in &mut ws.strips {
                    for g in &mut strip.window_groups {
                        if touched.contains(&g.id) {
                            g.width = crate::shell::state::WindowWidth::Fraction(permille);
                        }
                    }
                }
            }
            tree.queue_save();
        }
        // `RuntimeGroup::set_width` flags its own style dirty; the
        // frame loop's structure sweep is what rebuilds the taffy node
        // whose baked length carries the old width.
        touched
    }

    /// Close the active tab of the focused group, through the same
    /// `TabBar::start_closing` a `✕` click runs. `false` when nothing is
    /// focused or the group has no tab left to close.
    pub fn close_focused_tab(&mut self) -> bool {
        let Some(chrome) = self.chrome.clone() else {
            return false;
        };
        let focused = crate::shell::window_actions::focused_group(&chrome.borrow());
        let Some(gid) = focused else {
            return false;
        };
        self.close_tab_in_group(gid, None)
    }

    /// Close `tab` (or the active tab, when `tab` is `None`) in the group
    /// with id `gid`. Shared by the chord and the tab context menu.
    pub fn close_tab_in_group(&mut self, gid: GroupId, tab: Option<u64>) -> bool {
        for &ptr in self.group_row_ptrs.values() {
            // SAFETY: see field doc on `group_row_ptrs`.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            for g in &mut row.groups {
                if g.id != gid {
                    continue;
                }
                let tab_id = tab.unwrap_or_else(|| g.active_tab_id());
                let Some(chrome) = self.chrome.clone() else {
                    return false;
                };
                let close = tilo_desktop::intents::SessionIntent::CloseTab {
                    group: gid,
                    tab: tab_id,
                };
                if Self::dispatch_desktop_intents(
                    &chrome,
                    [tilo_desktop::intents::DesktopIntent::Session(close)],
                ) == 0
                {
                    return false;
                }
                // A foreign client's close request can be refused. Keep its
                // live tab visible until the compositor sees destruction.
                if Self::tab_still_present(&chrome, tab_id) {
                    g.cancel_tab_close(tab_id);
                    return true;
                }
                // The durable tree/document mutation must succeed before the
                // widget begins its close animation. A visual-only close is
                // precisely what allowed the next resync to restore a window.
                let closed = match tab {
                    Some(id) => g.request_close_tab(id),
                    None => g.request_close_active_tab(),
                };
                debug_assert!(closed, "tree and rendered tab strip diverged before close");
                return closed;
            }
        }
        false
    }

    fn tab_still_present(chrome: &Chrome, tab_id: u64) -> bool {
        chrome
            .borrow()
            .tree()
            .desktop
            .workspaces
            .iter()
            .flat_map(|workspace| workspace.strips.iter())
            .flat_map(|strip| strip.window_groups.iter())
            .flat_map(|group| group.tabs.iter())
            .any(|tab| tab.id == tab_id)
    }

    /// Drain close buttons from the rendered rows into the same lifecycle
    /// transaction used by keyboard closes. This is intentionally run in
    /// the input dispatch that produced the request, not on a later frame.
    #[allow(
        clippy::needless_pass_by_ref_mut,
        reason = "Exclusive access prevents aliases while raw row pointers are materialized as mutable rendered rows."
    )]
    fn harvest_pending_tab_closes(&mut self) -> bool {
        let Some(chrome) = self.chrome.clone() else {
            return false;
        };
        let mut intents = Vec::new();
        for &ptr in self.group_row_ptrs.values() {
            // SAFETY: see field doc on `group_row_ptrs`.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            for group in &mut row.groups {
                intents.extend(
                    tilo_desktop::intents::take_closes(group)
                        .into_iter()
                        .map(tilo_desktop::intents::DesktopIntent::Session),
                );
            }
        }
        let changed = Self::dispatch_desktop_intents(&chrome, intents) > 0;
        for &ptr in self.group_row_ptrs.values() {
            // SAFETY: the pointers belong to this exclusively borrowed host.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            for group in &mut row.groups {
                let retained: Vec<_> = chrome
                    .borrow()
                    .tree()
                    .desktop
                    .workspaces
                    .iter()
                    .flat_map(|workspace| workspace.strips.iter())
                    .flat_map(|strip| strip.window_groups.iter())
                    .filter(|model| model.id == group.id)
                    .flat_map(|model| model.tabs.iter())
                    .map(|tab| tab.id)
                    .collect();
                for tab in retained {
                    group.cancel_tab_close(tab);
                }
            }
        }
        changed
    }

    fn harvest_pending_width_changes(&self) {
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        let intents = self.take_group_intents(|group| {
            tilo_desktop::intents::take_width(group)
                .map(tilo_desktop::intents::DesktopIntent::Local)
        });
        Self::dispatch_desktop_intents(&chrome, intents);
    }

    /// Commits a completed whole-group reorder drag through the desktop
    /// controller — without this a group drag resets to the persisted order
    /// on restart.
    fn harvest_pending_group_reorder(&self) {
        // A partitioned row orders groups display by display, so its index
        // is not the strip's: record the display the group was dropped on
        // and its neighbours there instead.
        struct PartitionedDrop {
            strip: StripId,
            group: u64,
            display: Option<u32>,
            before: Option<u64>,
            after: Option<u64>,
        }
        if self.group_row_ptrs.is_empty() {
            return;
        }
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        let mut intents = Vec::new();
        let mut partitioned = Vec::new();
        for (&strip_id, &ptr) in &self.group_row_ptrs {
            // SAFETY: see field doc on `group_row_ptrs`.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            let Some(intent) = tilo_desktop::intents::take_group_reorder(strip_id, row) else {
                continue;
            };
            let tilo_desktop::intents::SessionIntent::ReorderGroup { group, .. } = intent else {
                continue;
            };
            if row.is_partitioned() {
                let ids = row.group_ids();
                let at = ids.iter().position(|id| *id == group);
                let before = at
                    .and_then(|i| i.checked_sub(1))
                    .and_then(|i| ids.get(i).copied())
                    .filter(|id| row.lane_of_group(*id) == row.lane_of_group(group));
                let after = at
                    .and_then(|i| ids.get(i.saturating_add(1)).copied())
                    .filter(|id| row.lane_of_group(*id) == row.lane_of_group(group));
                partitioned.push(PartitionedDrop {
                    strip: strip_id,
                    group,
                    display: row.output_of_group(group),
                    before,
                    after,
                });
            } else {
                intents.push(tilo_desktop::intents::DesktopIntent::Session(intent));
            }
        }
        if !partitioned.is_empty() {
            let mut st = chrome.borrow_mut();
            let mut rehomed = false;
            {
                let mut tree = st.tree_mut();
                for PartitionedDrop {
                    strip: strip_id,
                    group: group_id,
                    display,
                    before,
                    after,
                } in partitioned
                {
                    // Dropped onto another display: it belongs there now.
                    if let Some(display) = display
                        && tree.rehome_group(strip_id, group_id, display)
                    {
                        rehomed = true;
                    }
                    let order: Vec<u64> = tree
                        .desktop
                        .workspaces
                        .iter()
                        .flat_map(|w| &w.strips)
                        .find(|s| s.id == strip_id)
                        .map(|s| {
                            s.window_groups
                                .iter()
                                .map(|g| g.id)
                                .filter(|id| *id != group_id)
                                .collect()
                        })
                        .unwrap_or_default();
                    let slot = before
                        .and_then(|b| order.iter().position(|id| *id == b))
                        .map(|i| i.saturating_add(1))
                        .or_else(|| after.and_then(|a| order.iter().position(|id| *id == a)));
                    let Some(slot) = slot else {
                        continue;
                    };
                    let command = tilo_desktop_model::commands::DesktopCommand::ReorderGroup {
                        strip: strip_id.raw(),
                        group: group_id,
                        before: order.get(slot).copied(),
                    };
                    if let Err(error) = tree.commit_command(&command) {
                        tracing::warn!(%error, "group reorder refused");
                    }
                }
            }
            if rehomed {
                st.bump();
            }
        }
        Self::dispatch_desktop_intents(&chrome, intents);
    }

    /// Same as [`Self::harvest_pending_group_reorder`], for an
    /// *intra-group* tab reorder.
    fn harvest_pending_tab_reorder(&self) {
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        let intents = self.take_group_intents(|group| {
            tilo_desktop::intents::take_tab_reorder(group)
                .map(tilo_desktop::intents::DesktopIntent::Session)
        });
        Self::dispatch_desktop_intents(&chrome, intents);
    }

    /// Mirrors same-strip tab transfers and splits from the live rows into
    /// the persisted workspace tree. The row publishes only group/tab ids;
    /// the tree remains the sole owner of tile content and collaboration data.
    fn harvest_pending_group_topology(&self) {
        if self.group_row_ptrs.is_empty() {
            return;
        }
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        let mut changes = Vec::new();
        for (&strip_id, &ptr) in &self.group_row_ptrs {
            // SAFETY: same contract as the other row harvesters: the content
            // tree owns this pointer and harvest passes run sequentially.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            if let Some(topology) = row.take_pending_topology_change() {
                changes.push((strip_id, topology));
            }
        }
        if changes.is_empty() {
            return;
        }
        let state = chrome.borrow_mut();
        let mut tree = state.tree_mut();
        for (strip_id, topology) in changes {
            tree.reconcile_strip_topology(strip_id, &topology);
        }
    }

    /// Drains each group's [`UiWindowGroup::take_pending_search_open`]
    /// one-shot and opens the search bar scoped to the active app — the
    /// same entry point Ctrl+K uses. The palette lives on the host, not
    /// the group.
    fn harvest_pending_search_open(&mut self) {
        if self.group_row_ptrs.is_empty() {
            return;
        }
        let mut requested = None;
        for &ptr in self.group_row_ptrs.values() {
            // SAFETY: see field doc on `group_row_ptrs`.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            for g in &mut row.groups {
                if let Some(handoff) = g.take_pending_search_open() {
                    requested = Some(handoff);
                }
            }
        }
        let Some(handoff) = requested else {
            return;
        };
        // Mirror the widget-side active tab into the tree first so the scope
        // resolves to the app whose chip was clicked, not a stale pointer.
        self.harvest_active_tab_writeback();
        let scope = match handoff.reach {
            ui::widget::SearchReach::App => crate::shell::chrome_state::SearchScope::ActiveApp,
            ui::widget::SearchReach::Everywhere => crate::shell::chrome_state::SearchScope::All,
        };
        if handoff.query.is_empty() {
            // The control of a window with nothing to search in place: the
            // palette narrowed to its app, toggled as the chip always was.
            self.open_palette_with_scope(scope);
            return;
        }
        // A search widened from a window carries its query on; the palette
        // opens (never toggles closed) in the wider scope.
        let current = self
            .chrome
            .as_ref()
            .map(|c| c.borrow().search_scope)
            .unwrap_or_default();
        if !self.palette_visible || current != scope {
            self.open_palette_with_scope(scope);
        }
        self.palette.set_query(&handoff.query);
        self.palette_visible = true;
    }

    /// Whether a window's search field holds the keyboard
    /// ([`ui::widget::WindowSearch::has_keyboard`]).
    pub(crate) fn window_search_has_keyboard(&self) -> bool {
        self.group_row_ptrs.values().any(|&ptr| {
            // SAFETY: see field doc on `group_row_ptrs`.
            let row: &GroupRow = unsafe { &*ptr };
            row.groups
                .iter()
                .any(|group| group.window_search().has_keyboard())
        })
    }

    /// Give a keyboard or input-method event to the window whose search
    /// field holds the keyboard, ahead of every chord and focused control
    /// but the desktop's own (Super) ones: the field is a text field like
    /// any other. Whether it took it.
    fn route_window_search_input(
        &mut self,
        event: &WindowEvent,
        ctx: &mut ui::widget::EventCtx<'_>,
    ) -> bool {
        if !matches!(
            event,
            WindowEvent::KeyboardInput { .. } | WindowEvent::Ime(_)
        ) || ctx.modifiers.state().super_key()
            || self.palette_visible
        {
            return false;
        }
        let mut taken = false;
        for &ptr in self.group_row_ptrs.values() {
            // SAFETY: see field doc on `group_row_ptrs`.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            for group in &mut row.groups {
                taken |= group.route_search_input(event, &mut ctx.reborrow(ctx.path, ctx.node_id));
            }
        }
        if taken {
            self.harvest_pending_search_open();
        }
        taken
    }

    /// Sibling of [`Self::harvest_pending_search_open`] for the "+" chip:
    /// opens the palette aimed at that group rather than minting an
    /// assumed tab type. [`OpenTarget::Here`] pins the result to this
    /// group even when the placement rule would open beside it.
    fn harvest_pending_new_tab(&mut self) -> bool {
        if self.group_row_ptrs.is_empty() {
            return false;
        }
        let mut requested: Option<u64> = None;
        for &ptr in self.group_row_ptrs.values() {
            // SAFETY: see field doc on `group_row_ptrs`.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            for g in &mut row.groups {
                if let Some(id) = g.take_pending_new_tab() {
                    requested = Some(id);
                }
            }
        }
        let Some(group) = requested else {
            return false;
        };
        self.open_new_tab_palette_for_group(group);
        true
    }

    /// Configure the application picker opened by a group's `+` affordance.
    /// Split from the widget one-shot harvest so its scope/placement contract
    /// has direct regression coverage.
    fn open_new_tab_palette_for_group(&mut self, group: GroupId) {
        // Must run before the palette's scope resolution and launch path
        // read the active pointers.
        self.harvest_active_tab_writeback();
        if let Some(chrome) = self.chrome.clone() {
            let mut st = chrome.borrow_mut();
            st.open_target = crate::shell::chrome_state::OpenTarget::Here(group);
            // The group is the placement target and its workspace is the
            // search boundary. Machine-wide search belongs to Super+K; a
            // local "+" must not silently reach into other workspaces.
            st.search_scope = crate::shell::chrome_state::SearchScope::Workspace;
            st.search_resource_scope = None;
            st.bump();
        }
        // Narrowed to kinds that can *be* a tab, so results aren't buried
        // under notes/files/chrome actions the user has to read past.
        self.active_kind_filter = app_kind_filter();
        // Force-open, not `open_palette_with_scope`: that helper toggles
        // closed on a same-scope repeat, wrong for a "+" click.
        if !self.palette_visible {
            self.palette_visible = true;
            self.palette.set_focus(true);
            self.palette.set_query("");
        }
        // Re-run the query even when the palette was already up: the rows
        // carry a placement hint that just changed.
        self.last_search_query = "\u{0}not-yet-refreshed\u{0}".to_string();
    }

    /// Drops a stale `OpenTarget::Here` and kind filter once the palette
    /// closes — both are one-shot aims for a single launch, and a leaked
    /// filter would silently narrow the next unrelated query.
    fn clear_stale_open_target(&mut self) {
        if self.palette_visible {
            return;
        }
        if self.param_flow.is_some() || self.secondary_flow.is_some() {
            self.end_palette_steps();
        }
        self.expanded_kinds.clear();
        self.present_kinds.clear();
        self.palette
            .set_query_placeholder(t("host-search-placeholder"));
        self.active_kind_filter.clear();
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        let mut st = chrome.borrow_mut();
        if st.search_resource_scope.take().is_some() {
            st.bump();
        }
        if st.open_target != crate::shell::chrome_state::OpenTarget::Beside {
            st.open_target = crate::shell::chrome_state::OpenTarget::Beside;
            st.bump();
        }
    }

    /// Test-only one-shot: retire a dismissed palette's aim and filter.
    #[cfg(any(test, debug_assertions))]
    pub fn tick_clear_stale_open_target_for_tests(&mut self) {
        self.clear_stale_open_target();
    }

    /// Clears a typed wifi passphrase once the quick-settings popover
    /// closes, so it doesn't outlive the window it was entered in — and
    /// lets go of the field's value as soon as its prompt is gone, however
    /// it went.
    fn clear_stale_wifi_password(&mut self) {
        if let Some(chrome) = self.chrome.clone() {
            let open = chrome.borrow().overlays.quick_settings;
            let mut st = chrome.borrow_mut();
            if !open && st.quick_settings.wifi_password.take().is_some() {
                st.bump();
            }
        }
        self.sync_wifi_password_input();
    }

    /// Frames the focused group and lights its focus marker through the
    /// shared surface, from the tree's active strip and group. Framing is
    /// edge-triggered, so free wheel-scrolling isn't fought by a per-frame
    /// snap-back.
    fn scroll_active_group_into_view(&mut self) {
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        let st = chrome.borrow();
        let tree = st.tree();
        if let Some(surface) = self.desktop_surface_mut() {
            surface.sync_navigation(&tree.desktop);
        }
    }

    /// Publishes the active strip's laid-out geometry for
    /// [`crate::shell::placement`] to consult. Doesn't bump the chrome
    /// revision — this reports layout output, not a mutation to resync against.
    fn publish_strip_viewport(&self) {
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        let focused_display = self
            .is_partitioned()
            .then(|| chrome.borrow().tree().desktop.outputs.focused_display())
            .flatten();
        // Same resolution the placement rule performs.
        let strip_id = {
            let st = chrome.borrow();
            let tree = st.tree();
            tree.desktop.active_workspace().and_then(|ws| {
                tree.desktop
                    .active_strip
                    .get(&ws.id)
                    .copied()
                    .filter(|id| ws.strips.iter().any(|s| s.id == *id))
                    .or_else(|| ws.strips.first().map(|s| s.id))
            })
        };
        let viewport = strip_id.and_then(|sid| {
            let &ptr = self.group_row_ptrs.get(&sid)?;
            // SAFETY: see field doc on `group_row_ptrs`.
            let row: &GroupRow = unsafe { &*ptr };
            let (visible_x0, visible_x1) = row.visible_canvas_span();
            // On a partitioned strip, the focused display's windows only:
            // a new window opens where the person is looking.
            let focused = focused_display.map(|d| row.group_ids_on(d));
            Some(tilo_desktop_model::commands::StripViewport {
                strip: sid,
                groups: row
                    .group_canvas_spans()
                    .into_iter()
                    .filter(|(id, _, _)| focused.as_ref().is_none_or(|on| on.contains(id)))
                    .map(|(id, x0, x1)| tilo_desktop_model::commands::GroupSpan { id, x0, x1 })
                    .collect(),
                visible_x0,
                visible_x1,
            })
        });
        let mut state = chrome.borrow_mut();
        state.set_strip_viewport(viewport);
        state.set_viewport_size((self.rect.width(), self.rect.height()));
    }

    /// The strip other than `except` whose windows `p` is over (see
    /// [`GroupRow::covers`]).
    fn strip_over(&self, p: Point, except: StripId) -> Option<StripId> {
        self.group_row_ptrs.iter().find_map(|(&strip_id, &ptr)| {
            // SAFETY: read-only use under the stable row-pointer contract.
            let row: &GroupRow = unsafe { &*ptr };
            (strip_id != except && row.covers(p)).then_some(strip_id)
        })
    }

    /// Preview and commit cross-strip tab drops with one retained
    /// [`TabDropTarget`]. A release outside every sibling strip restores the
    /// source exactly; it never invents a same-strip fallback group.
    ///
    /// SAFETY: each pointer addresses a `GroupRow` owned by the content
    /// tree, the host outlives the content, and each row is only ever
    /// touched by one reconcile sweep at a time — the frame loop runs
    /// them sequentially, never re-entrantly.
    fn dispatch_cross_strip_detaches(&self) {
        if self.group_row_ptrs.is_empty() {
            return;
        }
        // Drain sources first: a later `accept_cross_strip_drop` borrows
        // the destination row mutably, conflicting with a held source
        // payload reference.
        let mut detaches: Vec<(StripId, CrossStripDetach)> = Vec::new();
        for (&strip_id, &ptr) in &self.group_row_ptrs {
            // SAFETY: see field doc on `group_row_ptrs` — pointer was
            // captured from a `Box<GroupRow>` owned through the content
            // tree, the host outlives the content, and reconcile sweeps
            // run sequentially so no other path is aliasing.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            if let Some(payload) = row.take_pending_cross_strip_detach() {
                detaches.push((strip_id, payload));
            }
        }
        if detaches.is_empty() {
            let source = self.group_row_ptrs.iter().find_map(|(&strip_id, &ptr)| {
                // SAFETY: read-only use under the stable row-pointer contract
                // documented above.
                unsafe { (&*ptr).tab_drag_active() }.then_some(strip_id)
            });
            let destination = source.and_then(|source| {
                let cursor = self.last_cursor?;
                self.strip_over(cursor, source)
                    .map(|strip_id| (strip_id, cursor))
            });
            for (&strip_id, &ptr) in &self.group_row_ptrs {
                // SAFETY: each distinct row is visited once, sequentially.
                let row: &mut GroupRow = unsafe { &mut *ptr };
                row.set_cross_strip_tab_drag_hover(
                    destination
                        .filter(|(destination, _)| *destination == strip_id)
                        .map(|(_, cursor)| cursor),
                );
            }
            return;
        }
        // The destination row already resolved and painted the complete
        // target while the pointer moved. Release consumes that enum verbatim.
        for (src_strip_id, payload) in detaches {
            let release = payload.release_point;
            let dest_strip_id = self.strip_over(release, src_strip_id);
            let Some(dest_strip_id) = dest_strip_id else {
                if let Some(&source_ptr) = self.group_row_ptrs.get(&src_strip_id) {
                    // SAFETY: source and destination routing is sequential.
                    unsafe { &mut *source_ptr }.restore_cross_strip_detach(payload);
                }
                continue;
            };
            // SAFETY: same contract as the drain above. We're mutating a
            // single row at a time and never aliasing across rows.
            let Some(&dest_ptr) = self.group_row_ptrs.get(&dest_strip_id) else {
                continue;
            };
            // One globally unique id is shared by the rendered group, the
            // durable cache and the replicated document. Generating an id
            // independently inside each strip made a later resync unable to
            // identify the group the person had just moved.
            let new_group_id = crate::shell::state::next_id();
            let target = {
                let dest_row: &GroupRow = unsafe { &*dest_ptr };
                dest_row
                    .cross_strip_drop_target()
                    // Synthetic/headless tests can stage a detach without a
                    // preceding motion frame; production uses the retained
                    // preview above.
                    .or_else(|| dest_row.tab_drop_target_at(release))
            };
            let Some(target) = target else {
                if let Some(&source_ptr) = self.group_row_ptrs.get(&src_strip_id) {
                    unsafe { &mut *source_ptr }.restore_cross_strip_detach(payload);
                }
                continue;
            };
            // Commit the cache + replicated document before moving the live
            // host. If the destination or document is stale, returning the
            // payload to its source avoids a visual-only layout that a later
            // resync would appear to resurrect.
            let committed = self.chrome.clone().is_some_and(|chrome| {
                let st = chrome.borrow_mut();
                st.tree_mut().move_tab_across_strips(
                    src_strip_id,
                    dest_strip_id,
                    payload.tab_id,
                    new_group_id,
                    target,
                )
            });
            if committed {
                let Some(&target_ptr) = self.group_row_ptrs.get(&dest_strip_id) else {
                    continue;
                };
                let target_row: &mut GroupRow = unsafe { &mut *target_ptr };
                let accepted = target_row.accept_cross_strip_drop(
                    new_group_id,
                    payload.desc,
                    payload.host,
                    target,
                );
                debug_assert!(accepted, "durable target must remain live through dispatch");
            } else if let Some(&source_ptr) = self.group_row_ptrs.get(&src_strip_id) {
                let source_row: &mut GroupRow = unsafe { &mut *source_ptr };
                source_row.restore_cross_strip_detach(payload);
            }
        }
        for &ptr in self.group_row_ptrs.values() {
            // SAFETY: dispatch is complete; retire the one-frame preview from
            // every row without touching content-drag state.
            unsafe { &mut *ptr }.set_cross_strip_tab_drag_hover(None);
        }
    }

    /// Turns app-launcher worker-thread failures into notifications (a clean
    /// launch/exit is silent — the window is the feedback). Returns whether
    /// anything was posted, so the caller can mark the frame dirty.
    #[expect(
        clippy::too_many_lines,
        reason = "launch failures, expiries and placement repair share one ordered drain"
    )]
    pub(crate) fn drain_launch_events(&mut self) -> bool {
        use crate::shell::launcher::LaunchEventKind;
        if self.desktop_controls.is_explicit() {
            return false;
        }
        // Expiry is independent of new launcher events: a daemonising parent
        // can exit and never produce another event or window.
        let timed_out = crate::shell::launcher::expire_pending_placements();
        let events = crate::shell::launcher::drain_events();
        if events.is_empty() && timed_out.is_empty() {
            return false;
        }
        let Some(chrome_handle) = self.chrome.clone() else {
            return false;
        };
        let mut posted = false;
        for package_id in timed_out {
            let settled = {
                let chrome = chrome_handle.borrow();
                let mut tree = chrome.tree_mut();
                crate::shell::peer_windows::mark_timed_out_restore(&mut tree, &package_id)
                    | crate::shell::peer_windows::settle_install(
                        &mut tree,
                        &package_id,
                        &t("host-app-did-not-open-body"),
                    )
            };
            if settled {
                chrome_handle.borrow_mut().bump();
            }
            crate::shell::catalogue::take_pending_launch(&package_id);
            {
                let mut st = chrome_handle.borrow_mut();
                st.push_notification_full(
                    tilo_desktop::notifications::Notification::new(
                        t("host-app-did-not-open-title"),
                        t("host-app-did-not-open-body"),
                    )
                    .with_severity(tilo_desktop::notifications::NotificationSeverity::Error)
                    .with_app_name(t("host-source-applications"))
                    .with_dismiss_after(crate::shell::launcher::LAUNCH_FAILURE_NOTICE_LIFETIME),
                );
                st.bump();
            }
            tracing::error!(
                target: "tilo::app_launch",
                %package_id,
                timeout_seconds = 15_u64,
                "application started but did not present a window before the launch deadline"
            );
            posted = true;
        }
        for event in events {
            // A window that went away without being closed was lost, however
            // the process then exited; a new start forgets an older loss.
            let lost = match &event.kind {
                LaunchEventKind::Exited | LaunchEventKind::Failed { .. } => {
                    crate::shell::launcher::take_launch_vanished(&event.package_id)
                }
                LaunchEventKind::Started { .. } => {
                    crate::shell::launcher::note_launch_restarted(&event.package_id);
                    false
                }
                LaunchEventKind::OutOfMemory(end) if end.closed_the_app() => {
                    crate::shell::launcher::take_launch_vanished(&event.package_id);
                    false
                }
                LaunchEventKind::SpawnFailed { .. }
                | LaunchEventKind::WindowLost { .. }
                | LaunchEventKind::OutOfMemory(_) => false,
            };
            // The windows that went away with the launch are worth keeping
            // only when memory ended it: then its notice reopens them where
            // they were. Any other end of the app forgets them.
            let lost_tabs = match &event.kind {
                LaunchEventKind::OutOfMemory(end) if !end.closed_the_app() => Vec::new(),
                LaunchEventKind::Started { .. } => Vec::new(),
                _ => crate::shell::launcher::take_lost_tabs(&event.package_id),
            };
            let event = event.with_window_lost(lost);
            if self.room_activity.observe_agent_launch_event(&event) {
                chrome_handle.borrow_mut().bump();
                posted = true;
            }
            // Memory ended the app or one of its jobs: say which and why,
            // whether or not its window had shown, and offer the app back
            // where it was.
            if let LaunchEventKind::OutOfMemory(end) = &event.kind {
                if end.closed_the_app() {
                    crate::shell::launcher::clear_pending_placement(&event.package_id);
                    crate::shell::catalogue::take_pending_launch(&event.package_id);
                    let _ = crate::shell::launcher::take_launch_presented(&event.package_id);
                }
                event.log_failure();
                if let Some(notice) = event.failure_notice() {
                    let mut st = chrome_handle.borrow_mut();
                    st.push_out_of_memory_notice(notice, lost_tabs);
                    st.bump();
                    posted = true;
                }
                continue;
            }
            // A failure settles the pending launch here. `Started`
            // doesn't — the window is still seconds away — that's
            // [`Self::settle_launches_of_opened_windows`]'s job. A clean
            // exit also settles it: a process can quit before presenting a
            // window, and the app must stay openable again.
            if matches!(
                event.kind,
                LaunchEventKind::SpawnFailed { .. } | LaunchEventKind::Failed { .. }
            ) {
                // A client can map before its launcher reports a terminal
                // failure.  Its foreign tab has no content yet, and keeping
                // it leaves an "Opening…" pane beside the failure toast.
                // The launcher only yields a surface when this is the sole
                // in-flight launch for the package, so concurrent launches
                // cannot make one failure close another app's window.
                if let Some(surface_id) =
                    crate::shell::launcher::take_sole_claimed_surface_for_failed_launch(
                        &event.package_id,
                    )
                    && {
                        let chrome = chrome_handle.borrow();
                        let mut tree = chrome.tree_mut();
                        crate::compositor::tab_binding::retire_starting_foreign_surface(
                            &mut tree, surface_id,
                        )
                    }
                {
                    chrome_handle.borrow_mut().bump();
                    posted = true;
                }
                // A failed process can never claim its promised toplevel, so
                // clear it at the same boundary as the pending launch.
                crate::shell::launcher::clear_pending_placement(&event.package_id);
                crate::shell::catalogue::take_pending_launch(&event.package_id);
            }
            if matches!(
                event.kind,
                LaunchEventKind::Exited | LaunchEventKind::WindowLost { .. }
            ) {
                // A successful launcher parent may have daemonised. Its GUI
                // child still owns this launch for a short bounded interval,
                // so settle the launch now but keep placement until a
                // matching toplevel claims it or the grace expires.
                crate::shell::launcher::retire_pending_placement_after_grace(&event.package_id);
                crate::shell::catalogue::take_pending_launch(&event.package_id);
            }
            match &event.kind {
                LaunchEventKind::Started { .. }
                | LaunchEventKind::Exited
                | LaunchEventKind::WindowLost { .. }
                | LaunchEventKind::OutOfMemory(_) => {
                    let _ = crate::shell::launcher::take_launch_presented(&event.package_id);
                }
                // Its window was up, so it did open; the window, and its
                // tab, are already gone.
                // A window that stopped on its own is never an ending the
                // person asked for, shown or not.
                LaunchEventKind::Failed { code, stderr_tail }
                    if !stderr_tail.contains(ui::app::WINDOW_LOST)
                        && crate::shell::launcher::take_launch_presented(&event.package_id) =>
                {
                    tracing::info!(
                        target: "shell::launcher",
                        package_id = %event.package_id,
                        display_name = %event.display_name,
                        exit_code = ?code,
                        "application exited with an error after showing its window"
                    );
                    continue;
                }
                // Geoclue and nm-applet are autostart helpers. They are not the
                // app the person opened, so their exit must not toast
                // "crashed before opening" for that launch.
                LaunchEventKind::Failed { .. }
                    if crate::shell::launcher::unasked_session_helper(&event.package_id) =>
                {
                    tracing::info!(
                        target: "shell::launcher",
                        package_id = %event.package_id,
                        display_name = %event.display_name,
                        "session helper exited without a window the user asked to open"
                    );
                    crate::shell::launcher::restart_session_helper(&event.package_id);
                    continue;
                }
                LaunchEventKind::Failed { .. } | LaunchEventKind::SpawnFailed { .. } => {}
            }
            match &event.kind {
                LaunchEventKind::Started { pid } => {
                    tracing::info!(
                        target: "shell::launcher",
                        package_id = %event.package_id,
                        display_name = %event.display_name,
                        pid,
                        "application process started"
                    );
                    continue;
                }
                LaunchEventKind::Exited => {
                    tracing::info!(
                        target: "shell::launcher",
                        package_id = %event.package_id,
                        display_name = %event.display_name,
                        "application process exited successfully"
                    );
                    continue;
                }
                LaunchEventKind::SpawnFailed { .. }
                | LaunchEventKind::Failed { .. }
                | LaunchEventKind::WindowLost { .. }
                | LaunchEventKind::OutOfMemory(_) => {}
            }
            event.log_failure();
            let Some(notice) = event.failure_notice() else {
                continue;
            };
            let settled = {
                let chrome = chrome_handle.borrow();
                let mut tree = chrome.tree_mut();
                crate::shell::peer_windows::settle_local_restore(
                    &mut tree,
                    &event.package_id,
                    &notice.body,
                ) | crate::shell::peer_windows::settle_install(
                    &mut tree,
                    &event.package_id,
                    &notice.body,
                )
            };
            if settled {
                chrome_handle.borrow_mut().bump();
            }
            let mut st = chrome_handle.borrow_mut();
            st.push_notification_full(
                tilo_desktop::notifications::Notification::new(notice.title, notice.body)
                    .with_severity(tilo_desktop::notifications::NotificationSeverity::Error)
                    .with_app_name(t("host-source-applications"))
                    .with_dismiss_after(crate::shell::launcher::LAUNCH_FAILURE_NOTICE_LIFETIME),
            );
            st.bump();
            posted = true;
        }
        posted
    }

    /// Typed `session.*` actions invoked since the last update, run by the
    /// executor the power flyout uses.
    fn run_requested_session_actions(&self) {
        let Some(chrome) = self.chrome.as_ref() else {
            return;
        };
        let requests = chrome.borrow_mut().take_session_action_requests();
        for action in requests {
            self.execute_session_action(action);
        }
    }

    fn drain_session_action_results(&self) -> bool {
        let mut posted = false;
        while let Ok(outcome) = self.session_action_channel.1.try_recv() {
            let Err(error) = outcome.result else {
                continue;
            };
            tracing::warn!(
                target: "tilo::os_actions",
                action = ?outcome.action,
                error = %error,
                "session action failed"
            );
            let Some(chrome) = self.chrome.as_ref() else {
                continue;
            };
            let body = match outcome.action {
                os_actions::SessionAction::Lock => t("host-session-lock-failed"),
                os_actions::SessionAction::Logout => t("host-session-logout-failed"),
                os_actions::SessionAction::SwitchUser => t("host-session-switch-user-failed"),
                os_actions::SessionAction::Suspend => t("host-session-suspend-failed"),
                os_actions::SessionAction::Restart => t("host-session-restart-failed"),
                os_actions::SessionAction::ShutDown => t("host-session-shut-down-failed"),
            };
            chrome.borrow_mut().push_notification_full(
                tilo_desktop::notifications::Notification::new(
                    t("host-session-action-failed"),
                    body,
                )
                .with_severity(tilo_desktop::notifications::NotificationSeverity::Error)
                .with_app_name(t("host-source-system"))
                .with_dismiss_after(crate::shell::launcher::LAUNCH_FAILURE_NOTICE_LIFETIME),
            );
            posted = true;
        }
        posted
    }

    /// Settles the pending launch of any app now on screen, so it can be
    /// opened again. Neither `Started` (forked, no window yet) nor an
    /// adopted-but-not-presenting tab counts — what settles it is the app's
    /// first frame or placeholder card, whichever shows first.
    pub(crate) fn settle_launches_of_opened_windows(&self) -> bool {
        if self.desktop_controls.is_explicit() {
            return false;
        }
        let pending = crate::shell::catalogue::pending_launches();
        if pending.is_empty() {
            return false;
        }
        let Some(chrome_handle) = self.chrome.clone() else {
            return false;
        };
        let painted: Vec<String> = {
            let st = chrome_handle.borrow();
            st.tree()
                .desktop
                .workspaces
                .iter()
                .flat_map(|w| w.strips.iter())
                .flat_map(|s| s.window_groups.iter())
                .flat_map(|g| g.tabs.iter())
                .filter_map(|t| match &t.tile {
                    crate::shell::state::TileContent::Foreign { app_id, surface_id }
                        if {
                            let store = crate::compositor::foreign::store();
                            store.is_presented(*surface_id) || store.is_opening(*surface_id)
                        } =>
                    {
                        Some(app_id.clone())
                    }
                    _ => None,
                })
                .collect()
        };
        if painted.is_empty() {
            return false;
        }
        let mut retired = false;
        for package_id in pending {
            let showing = painted
                .iter()
                .any(|id| crate::shell::launcher::app_id_matches_package(id, &package_id));
            if !showing {
                continue;
            }
            retired |= crate::shell::catalogue::take_pending_launch(&package_id);
        }
        retired
    }

    pub fn pump_permission_prompt(&mut self) {
        let Some(chrome_handle) = self.chrome.clone() else {
            return;
        };

        // A retired native/portal request cannot leave a stale grant sheet.
        chrome_handle
            .borrow_mut()
            .pending_grants
            .retain(|pending| !pending.is_retired());

        // The widget and semantic actions answer the same exact pending request.
        let choice = self
            .permission_prompt
            .as_ref()
            .and_then(|p| p.pending_choice);
        if let Some(choice) = choice {
            if let Some(id) = self.permission_prompt_id {
                let _ = crate::shell::search::providers::permission_prompts::answer_pending_prompt(
                    &mut chrome_handle.borrow_mut(),
                    id,
                    choice,
                );
            }
            self.permission_prompt = None;
            self.permission_prompt_id = None;
        }
        let head_id = chrome_handle.borrow().pending_grants.front().map(|p| p.id);
        if self.permission_prompt_id != head_id {
            self.permission_prompt = None;
            self.permission_prompt_id = None;
        }

        // Step 2 — latch a new prompt when the queue's front needs
        // surfacing and we don't already hold a widget.
        if self.permission_prompt.is_none() {
            let st = chrome_handle.borrow();
            if let Some(pending) = st.pending_grants.front() {
                self.permission_prompt_id = Some(pending.id);
                self.permission_prompt_app = Some(pending.app_id.clone());
                let label = prompt_label(&pending.request);
                let is_owner = is_active_workspace_owner(&st);
                self.permission_prompt = Some(PermissionPrompt::new(
                    pending.app_id.clone(),
                    label,
                    is_owner,
                ));
            }
        }
    }

